// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"labetalol":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Gefässe erweitert und das Herz vor Stresshormonen abschirmt. Labetalol blockiert nicht-selektiv Beta-Rezeptoren und zusätzlich Alpha-1-Rezeptoren der Gefässmuskulatur (Beta- zu Alpha-Wirkung etwa 3:1 als Tablette, 7:1 intravenös). Dadurch sinkt der Gefässwiderstand, ohne dass der Puls reflektorisch ansteigt.","nebenwirkungen":{"haeufig":["Orthostatische Hypotonie (Schwindel beim Aufstehen), besonders zu Beginn","Müdigkeit, Kopfschmerzen, Schwindel","Vorübergehendes Kribbeln der Kopfhaut","Verstopfte Nase","Knöchelödeme","Ejakulationsstörungen"],"sehrSelten":["Leberentzündung, Gelbsucht und Leberzellschädigung","Lupus-ähnliche Erkrankung, positive antinukleäre Antikörper","Muskelerkrankung (toxische Myopathie)"],"unbekannt":["Bradykardie (langsamer Puls), AV-Block","Bronchospasmus (Verkrampfung der Atemwege)","Hautausschlag","Verdeckte Unterzuckerungszeichen bei Diabetes"]},"schwangerschaft":"Wird zur Behandlung von Bluthochdruck in der Schwangerschaft eingesetzt (ärztliche Verordnung). Beim Neugeborenen können vorübergehend langsamer Puls, Blutdruckabfall, Unterzuckerung und Atemprobleme auftreten.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich, Säugling auf langsamen Puls und Unterzuckerung beobachten.","hinweise":["Tabletten mit einer Mahlzeit einnehmen.","Langsam aufstehen, besonders zu Beginn der Behandlung (Schwindel, Ohnmacht).","Nicht abrupt absetzen, sondern ausschleichen.","Bei Gelbsucht, dunklem Urin, anhaltender Übelkeit oder Oberbauchschmerzen sofort ärztlich melden (Leberschaden)."],"darreichung":["Tabletten","Filmtabletten","Injektionslösung"]},"lacidipin":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Blutgefässe erweitert. Lacidipin blockiert L-Typ-Calciumkanäle in der glatten Muskulatur der Arterien und senkt so den Gefässwiderstand. Wegen seiner hohen Fettlöslichkeit reichert es sich in den Zellmembranen an und wirkt trotz kurzer Halbwertszeit über 24 Stunden. Die Wirkung setzt langsam ein, sodass eine reflektorische Pulsbeschleunigung meist gering bleibt.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Herzklopfen, Herzrasen","Flush (Hautrötung mit Wärmegefühl)","Knöchelödeme (Schwellungen)","Übelkeit, Bauchbeschwerden","Polyurie (vermehrtes Wasserlassen)","Hautausschlag mit Rötung und Juckreiz","Asthenie (Schwächegefühl)"],"gelegentlich":["Verstärkung einer bestehenden Angina pectoris","Synkope (Ohnmacht)","Hypotonie (tiefer Blutdruck)","Gingivahyperplasie (Zahnfleischwucherung)"],"selten":["Angioödem (Schwellung von Gesicht, Lippen oder Rachen)","Nesselsucht","Muskelkrämpfe"],"sehrSelten":["Tremor (Zittern)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; nur anwenden, wenn eindeutig erforderlich. Lacidipin kann die Gebärmuttermuskulatur entspannen und so die Wehen beeinflussen.","stillzeit":"Nicht empfohlen, da Lacidipin im Tierversuch in die Milch übergeht.","hinweise":["Einmal täglich möglichst zur gleichen Tageszeit, am besten morgens, einnehmen; kein Grapefruitsaft.","Zu Beginn können Schwindel und Kopfschmerzen auftreten – Vorsicht beim Autofahren.","Auf gute Mundhygiene achten, da Zahnfleischwucherungen möglich sind."],"darreichung":["Filmtabletten"]},"lacosamid":{"wirkmechanismus":"Beruhigt überaktive Nervenzellen und verhindert so Krampfanfälle. Lacosamid verstärkt selektiv die langsame Inaktivierung spannungsabhängiger Natriumkanäle; dadurch werden dauerhaft übererregte Nervenmembranen stabilisiert, ohne die normale Signalübertragung stark zu beeinträchtigen. Es wird teils in der Leber (u. a. über CYP2C19, CYP3A4, CYP2C9) abgebaut und teils unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Schwindel, Kopfschmerzen","Doppelbilder","Übelkeit"],"haeufig":["Depression, Verwirrtheit, Schlaflosigkeit","Gleichgewichts- und Koordinationsstörungen, Gedächtnis- und Konzentrationsstörungen, Schläfrigkeit, Zittern, Augenzittern, Kribbeln, Sprechstörungen","Verschwommenes Sehen, Drehschwindel, Ohrensausen","Erbrechen, Verstopfung, Blähungen, Verdauungsbeschwerden, Mundtrockenheit, Durchfall","Juckreiz, Hautausschlag","Muskelkrämpfe, Gangstörungen, Stürze","Müdigkeit, Schwäche, Reizbarkeit"],"gelegentlich":["AV-Block, langsamer Puls (Bradykardie), PR-Verlängerung, Vorhofflimmern oder -flattern","Ohnmacht (Synkope)","Aggression, Unruhe, Halluzinationen, Psychose, Suizidgedanken und -versuche","Überempfindlichkeitsreaktionen, Angioödem, Nesselsucht","Erhöhte Leberwerte"],"unbekannt":["Agranulozytose (Verlust der weissen Blutkörperchen)","Multiorgan-Überempfindlichkeitsreaktion (DRESS)","Krampfanfälle","Ventrikuläre Herzrhythmusstörungen","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur anwenden, wenn der Nutzen das mögliche Risiko klar überwiegt. Nicht eigenmächtig absetzen.","stillzeit":"Geht in die Muttermilch über; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Bei Herzerkrankungen oder herzwirksamen Begleitmitteln vor Beginn und nach Dosissteigerung ein EKG machen lassen.","Bei Herzklopfen, sehr langsamem Puls, Schwindel oder Ohnmacht sofort ärztlich melden.","Nicht abrupt absetzen – Gefahr von Krampfanfällen.","Alkohol meiden; Vorsicht beim Autofahren."],"darreichung":["Filmtabletten","Sirup","Infusionslösung"]},"lactobacillen":{"wirkmechanismus":"Enthält lebende Milchsäurebakterien (Lactobacillen), die die natürliche Darmflora unterstützen sollen. Die Bakterien bilden Milchsäure, senken den pH-Wert im Darm und erschweren so das Wachstum krankmachender Keime, mit denen sie um Nährstoffe und Haftstellen an der Schleimhaut konkurrieren. Sie werden nicht ins Blut aufgenommen und siedeln sich nur vorübergehend an.","nebenwirkungen":{},"schwangerschaft":"Schädliche Wirkungen sind nicht bekannt; Anwendung nach Rücksprache mit Ärztin, Arzt oder Apotheke.","stillzeit":"Schädliche Wirkungen sind nicht bekannt; Anwendung nach Rücksprache mit Ärztin, Arzt oder Apotheke.","hinweise":["Nicht mit heissen Getränken oder Speisen einnehmen (Wärme schädigt die Bakterien); Pulver in lauwarme oder kalte Flüssigkeit einrühren.","Während einer Antibiotikabehandlung zeitversetzt zum Antibiotikum einnehmen.","Bei Durchfall viel trinken; hält er länger als 2 Tage an oder treten Fieber oder Blut im Stuhl auf, ärztlich abklären lassen."],"darreichung":["Kapseln","Pulver (Beutel)"]},"lactulose":{"wirkmechanismus":"Hält Wasser im Darm zurück und macht so den Stuhl weicher und voluminöser. Lactulose ist ein künstlicher Zweifachzucker aus Galactose und Fructose, der im Dünndarm weder gespalten noch aufgenommen wird. Im Dickdarm bauen Bakterien ihn zu kurzkettigen Säuren (z. B. Milch- und Essigsäure) ab; dadurch sinkt der pH-Wert, der osmotische Druck steigt und die Darmbewegung wird angeregt. Bei hepatischer Enzephalopathie bindet das saure Milieu Ammoniak als Ammonium, das nicht ins Blut übertreten kann, und fördert ammoniakverwertende Bakterien – der Ammoniakspiegel im Blut sinkt. Die abführende Wirkung tritt nach 24–48 Stunden ein.","nebenwirkungen":{"sehrHaeufig":["Durchfall (vor allem bei hoher Dosis)"],"haeufig":["Blähungen (Flatulenz), besonders in den ersten Tagen","Bauchschmerzen","Übelkeit, Erbrechen"],"gelegentlich":["Störungen des Elektrolythaushalts infolge von Durchfall"],"unbekannt":["Überempfindlichkeitsreaktionen mit Hautausschlag, Juckreiz oder Nesselsucht"]},"schwangerschaft":"Kann angewendet werden; Lactulose wird praktisch nicht ins Blut aufgenommen.","stillzeit":"Kann angewendet werden.","hinweise":["Die abführende Wirkung setzt erst nach 1–2 Tagen ein; täglich ausreichend trinken.","Blähungen zu Beginn sind häufig und lassen meist nach einigen Tagen nach.","Den Sirup pur oder verdünnt, z. B. mit Wasser oder Saft, einnehmen."],"darreichung":["Sirup (Lösung zum Einnehmen)"]},"lamivudin":{"wirkmechanismus":"Hemmt die Vermehrung von HIV und Hepatitis-B-Viren. Lamivudin ist ein Cytidin-Analogon, das in den Zellen zu Lamivudin-Triphosphat phosphoryliert wird. Dieses wird von der Reversen Transkriptase von HIV bzw. der Polymerase des Hepatitis-B-Virus anstelle des natürlichen Bausteins in die Virus-DNA eingebaut und bricht die Kettenverlängerung ab. Allein eingesetzt werden die Viren rasch resistent (Mutation M184V bei HIV, YMDD-Mutation bei Hepatitis B).","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schlaflosigkeit","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall","Husten, Nasenbeschwerden","Hautausschlag, Haarausfall","Gelenk- und Muskelbeschwerden","Müdigkeit, Unwohlsein, Fieber"],"gelegentlich":["Neutropenie, Anämie, Thrombozytopenie (Veränderungen des Blutbilds)","Vorübergehend erhöhte Leberwerte"],"selten":["Pankreatitis (Bauchspeicheldrüsenentzündung)","Angioödem (Schwellung von Haut und Schleimhäuten)","Rhabdomyolyse (Muskelzerfall)","Hepatitis","Erhöhte Amylase"],"sehrSelten":["Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Erythroblastopenie (Aplasie der roten Blutzellen)","Laktatazidose (Übersäuerung des Blutes)"]},"schwangerschaft":"Kann bei Bedarf in der Schwangerschaft angewendet werden; umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); Lamivudin geht in die Muttermilch über. Bei Hepatitis B ohne HIV ist das Stillen mit der behandelnden Fachperson zu besprechen.","hinweise":["Unabhängig von den Mahlzeiten einnehmen; bei HIV täglich ohne Unterbrechung, damit keine Resistenzen entstehen.","Bei Hepatitis B nicht eigenmächtig absetzen – nach dem Absetzen Leberwerte über Monate kontrollieren.","Die Hepatitis-B-Dosis (100 mg) ist für die Behandlung von HIV zu niedrig."],"darreichung":["Filmtabletten","Lösung zum Einnehmen"]},"lamotrigin":{"wirkmechanismus":"Beruhigt überaktive Nervenzellen und verhindert so Krampfanfälle; stabilisiert zudem die Stimmung. Lamotrigin blockiert spannungsabhängige Natriumkanäle und hemmt dadurch die übermässige Freisetzung des erregenden Botenstoffs Glutamat. Es wird in der Leber durch Glucuronidierung abgebaut; Valproinsäure hemmt diesen Abbau, Enzyminduktoren und Östrogene beschleunigen ihn.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Hautausschlag"],"haeufig":["Aggression, Reizbarkeit","Schläfrigkeit, Schwindel, Zittern, Schlaflosigkeit, Unruhe","Übelkeit, Erbrechen, Durchfall, Mundtrockenheit","Gelenkschmerzen, Rückenschmerzen","Müdigkeit"],"gelegentlich":["Gang- und Koordinationsstörungen (Ataxie)","Doppelbilder, verschwommenes Sehen","Haarausfall"],"selten":["Stevens-Johnson-Syndrom","Augenzittern (Nystagmus)","Aseptische Meningitis (nicht-bakterielle Hirnhautentzündung)","Bindehautentzündung"],"sehrSelten":["Toxische epidermale Nekrolyse, DRESS (Multiorgan-Überempfindlichkeitsreaktion)","Blutbildveränderungen (Neutropenie, Thrombozytopenie, aplastische Anämie, Agranulozytose)","Hämophagozytische Lymphohistiozytose","Leberversagen, Leberfunktionsstörung","Verwirrtheit, Halluzinationen, Tics","Bewegungsstörungen, Verschlechterung einer Parkinson-Krankheit, Zunahme von Anfällen","Lupus-ähnliche Reaktionen"],"unbekannt":["Lymphknotenschwellung","Albträume"]},"schwangerschaft":"Nach heutigen Daten kein wesentlich erhöhtes Fehlbildungsrisiko; Anwendung nach ärztlicher Abwägung möglich. Die Spiegel sinken in der Schwangerschaft und steigen nach der Geburt – engmaschige Kontrollen; Folsäure-Einnahme empfohlen.","stillzeit":"Geht in die Muttermilch über, beim Säugling können relevante Spiegel entstehen; Stillen nach ärztlicher Abwägung möglich, Kind auf Ausschlag, Schläfrigkeit und Trinkschwäche beobachten.","hinweise":["Dosis nur langsam nach Plan steigern; bei Hautausschlag, Fieber, Schleimhautblasen oder Lymphknotenschwellung sofort ärztlich melden.","Nach einer Pause von mehr als 5 Halbwertszeiten nicht mit der vollen Dosis neu beginnen, sondern erneut einschleichen.","Nicht abrupt absetzen – Gefahr von Krampfanfällen.","Beginn oder Absetzen der Pille ärztlich mitteilen (Dosisanpassung)."],"darreichung":["Tabletten","Dispergierbare Tabletten / Kautabletten"]},"lanadelumab":{"wirkmechanismus":"Verhindert die übermässige Bildung von Bradykinin, das beim erblichen Angioödem die Schwellungen auslöst. Lanadelumab ist ein vollständig humaner monoklonaler Antikörper (IgG1), der das Enzym Plasmakallikrein bindet und hemmt. Plasmakallikrein spaltet hochmolekulares Kininogen zu Bradykinin und ist bei fehlendem oder unwirksamem C1-Esterase-Inhibitor ungenügend gebremst. Dank der langen Halbwertszeit von rund 2 Wochen genügt eine Injektion alle 2 bis 4 Wochen.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Schmerz, Rötung, Bluterguss, Juckreiz, Schwellung)"],"haeufig":["Überempfindlichkeitsreaktionen (z. B. Juckreiz, Missempfindungen an der Zunge)","Schwindel","Makulopapulöser Hautausschlag","Muskelschmerzen (Myalgie)","Erhöhte Leberwerte (ALT, AST)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; vorsichtshalber möglichst nicht anwenden, ausser nach sorgfältiger ärztlicher Abwägung.","stillzeit":"Antikörper gehen in den ersten Tagen nach der Geburt in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Nach Schulung selbst unter die Haut spritzen (Bauch, Oberschenkel, Oberarm); im Kühlschrank lagern.","Für akute Attacken trotzdem immer ein Notfallmedikament (z. B. Icatibant oder C1-Esterase-Inhibitor) mitführen.","Vor Gerinnungstests auf die Behandlung hinweisen."],"darreichung":["Injektionslösung in Fertigspritze oder Durchstechflasche (unter die Haut)"]},"lanreotid":{"wirkmechanismus":"Bremst die Ausschüttung von Wachstumshormon und von Hormonen aus neuroendokrinen Tumoren. Lanreotid ist ein lang wirksames Analogon des körpereigenen Hormons Somatostatin und bindet vor allem an die Somatostatin-Rezeptoren SSTR2 und SSTR5. Dadurch sinken Wachstumshormon und IGF-1, und die Freisetzung von Hormonen wie Serotonin aus neuroendokrinen Tumoren wird gehemmt; zusätzlich wirkt es wachstumshemmend auf diese Tumoren. Die Depotform bildet unter der Haut ein Reservoir, das den Wirkstoff über Wochen abgibt.","nebenwirkungen":{"sehrHaeufig":["Durchfall, weicher Stuhl","Bauchschmerzen","Gallensteine (Cholelithiasis)"],"haeufig":["Übelkeit, Erbrechen, Verstopfung, Blähungen","Fettstühle (Steatorrhö)","Unter- oder Überzuckerung, Diabetes","Sinusbradykardie (langsamer Puls)","Schwindel, Kopfschmerzen, Müdigkeit","Reaktionen an der Injektionsstelle (Schmerzen, Verhärtung)","Haarausfall","Erhöhte Leber- und Gallenwerte, Gewichtsabnahme"],"gelegentlich":["Hitzewallungen","Schlaflosigkeit","Entfärbter Stuhl"],"unbekannt":["Bauchspeicheldrüsenentzündung (Pankreatitis)","Gallenblasen- oder Gallengangsentzündung","Allergische Reaktionen (Angioödem, Anaphylaxie, Nesselsucht)","Abszess an der Injektionsstelle"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Wird alle 28 Tage tief unter die Haut gespritzt; nach Schulung auch durch Betroffene oder Angehörige möglich.","Regelmässige Kontrollen von Blutzucker, Gallenblase (Ultraschall) und Schilddrüse.","Starke Oberbauchschmerzen, Fieber oder Gelbsucht ärztlich abklären (Gallensteine, Gallenblasen- oder Bauchspeicheldrüsenentzündung)."],"darreichung":["Injektionslösung in Fertigspritze (Depot)"]},"lansoprazol":{"wirkmechanismus":"Senkt die Bildung von Magensäure stark und anhaltend. Lansoprazol wird in den sauren Belegzellen der Magenschleimhaut in seine aktive Form umgewandelt und blockiert dort irreversibel die Protonenpumpe (H+/K+-ATPase), den letzten Schritt der Säurebildung. Da neue Pumpen erst nachgebildet werden müssen, hält die Wirkung länger an, als der Wirkstoff im Blut vorhanden ist. Lansoprazol wird über CYP2C19 und CYP3A4 abgebaut und kann CYP1A2 leicht induzieren.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Übelkeit, Erbrechen, Bauchschmerzen","Durchfall, Verstopfung, Blähungen","Mund- oder Rachentrockenheit","Erhöhte Leberwerte","Nesselsucht, Juckreiz, Hautausschlag","Müdigkeit","Gutartige Drüsenpolypen im Magen (Fundusdrüsenpolypen)"],"gelegentlich":["Thrombozytopenie, Leukopenie, Eosinophilie (Veränderungen des Blutbilds)","Depression","Gelenk- und Muskelschmerzen","Knochenbrüche (Hüfte, Handgelenk, Wirbelsäule)","Wassereinlagerungen (Ödeme)"],"selten":["Schlaflosigkeit, Unruhe, Verwirrtheit, Halluzinationen","Kribbeln, Zittern, Benommenheit","Seh- und Geschmacksstörungen","Pankreatitis (Bauchspeicheldrüsenentzündung), Pilzbefall der Speiseröhre","Hepatitis, Gelbsucht","Erythema multiforme, Lichtempfindlichkeit, Haarausfall","Interstitielle Nephritis (Nierenentzündung)","Angioödem, Fieber, Gynäkomastie (Brustvergrösserung beim Mann)"],"sehrSelten":["Agranulozytose, Panzytopenie (schwerer Mangel an Blutzellen)","Anaphylaktischer Schock","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Kolitis, Stomatitis (Mundschleimhautentzündung)","Hyponatriämie (Natriummangel)"],"unbekannt":["Hypomagnesiämie (Magnesiummangel), dadurch auch Calcium- und Kaliummangel","Subakuter kutaner Lupus erythematodes","Mikroskopische Kolitis","DRESS (schwere Arzneimittelreaktion mit Ausschlag, Fieber und Organbeteiligung)"]},"schwangerschaft":"Erfahrungen sind begrenzt; in der Schwangerschaft nicht empfohlen und nur nach ärztlicher Abwägung anwenden.","stillzeit":"Ein Übergang in die Muttermilch ist wahrscheinlich; nur nach ärztlicher Nutzen-Risiko-Abwägung anwenden.","hinweise":["Morgens mindestens 30 Minuten vor dem Frühstück einnehmen – Nahrung vermindert die Aufnahme deutlich.","Kapseln ganz schlucken; Schmelztabletten auf der Zunge zergehen lassen, nicht kauen.","Nach längerer Einnahme nicht abrupt absetzen: vorübergehend vermehrte Säurebildung (Rebound) möglich.","Bei Langzeitbehandlung regelmässig die Notwendigkeit sowie Magnesium und Vitamin B12 überprüfen lassen."],"darreichung":["Magensaftresistente Kapseln","Schmelztabletten"]},"lanthan":{"wirkmechanismus":"Bindet Phosphat aus der Nahrung bereits im Magen-Darm-Trakt, sodass weniger davon ins Blut gelangt. Lanthancarbonat setzt im sauren Magenmilieu Lanthan-Ionen frei, die mit Nahrungsphosphat schwer lösliches Lanthanphosphat bilden. Dieses wird mit dem Stuhl ausgeschieden. Lanthan selbst wird nur in sehr geringem Mass aufgenommen und über die Galle ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Bauchschmerzen, Durchfall","Übelkeit, Erbrechen"],"haeufig":["Verstopfung","Verdauungsbeschwerden, Blähungen","Hypokalzämie (Calciummangel)"],"gelegentlich":["Darmverschluss (Ileus, Subileus)","Schwindel, Geschmacksstörung","Entzündung von Speiseröhre oder Mundschleimhaut","Gelenk- und Muskelschmerzen","Haarausfall, vermehrtes Schwitzen","Hyperkalzämie (zu viel Calcium im Blut)"],"unbekannt":["Darmdurchbruch (Perforation)","Allergische Hautreaktionen"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; in Tierversuchen bei hohen Dosen reproduktionstoxisch. Nicht empfohlen.","stillzeit":"Nicht bekannt, ob Lanthan in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Kautabletten vollständig zerkauen, nicht ganz schlucken; mit oder direkt nach einer Mahlzeit einnehmen.","Andere Arzneimittel mit Abstand einnehmen (meist mindestens 2 Stunden).","Starke Bauchschmerzen oder anhaltende Verstopfung ärztlich melden."],"darreichung":["Kautabletten","Pulver zum Einnehmen"]},"lapatinib":{"wirkmechanismus":"Blockiert Wachstumssignale in Brustkrebszellen mit zu vielen HER2-Rezeptoren. Lapatinib hemmt reversibel die Tyrosinkinasen der Rezeptoren HER2 (ErbB2) und EGFR (ErbB1) im Zellinnern. Dadurch werden die nachgeschalteten Signalwege (MAPK, PI3K/AKT) unterbrochen, die Zellteilung gebremst und der Zelltod gefördert.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen, Dyspepsie (Verdauungsbeschwerden), Stomatitis","Hautausschlag, trockene Haut, Hand-Fuss-Syndrom (mit Capecitabin)","Nagelveränderungen, Nagelbettentzündung, Haarausfall","Appetitlosigkeit, Müdigkeit","Schlaflosigkeit, Kopfschmerzen","Schmerzen in Rücken und Gliedern","Nasenbluten, Hitzewallungen (mit Aromatasehemmer)"],"haeufig":["Abnahme der Herzleistung (verminderte Auswurffraktion)","Erhöhtes Bilirubin, erhöhte Leberwerte"],"gelegentlich":["Schwere Leberschäden (Hepatotoxizität)","Interstitielle Lungenerkrankung, Pneumonitis"],"selten":["Schwere Überempfindlichkeitsreaktionen einschliesslich Anaphylaxie"],"unbekannt":["QT-Verlängerung und ventrikuläre Herzrhythmusstörungen (Torsade de Pointes)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"]},"schwangerschaft":"Nicht anwenden, ausser wenn unbedingt nötig. Frauen müssen während und mindestens 5 Tage nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 5 Tage nach der letzten Dosis nicht stillen.","hinweise":["Einmal täglich mindestens 1 Stunde vor oder 1 Stunde nach einer Mahlzeit einnehmen, immer gleich in Bezug auf das Essen.","Grapefruit und Grapefruitsaft meiden.","Bei Durchfall früh mit dem verordneten Mittel (z. B. Loperamid) beginnen, viel trinken und bei Fieber oder schwerem Durchfall sofort ärztlich melden.","Regelmässige Kontrollen: Herzfunktion, EKG, Elektrolyte und Leberwerte."],"darreichung":["Filmtabletten"]},"laronidase":{"wirkmechanismus":"Ersetzt ein fehlendes Enzym, damit sich bestimmte Zuckerketten (Glykosaminoglykane) nicht mehr in Geweben und Organen anhäufen. Laronidase ist eine gentechnisch hergestellte Alpha-L-Iduronidase. Sie wird über Mannose-6-Phosphat-Rezeptoren in die Zellen aufgenommen und baut in den Lysosomen Dermatansulfat und Heparansulfat ab. Auf die Beteiligung des Nervensystems wirkt sie nicht, da sie kaum ins Gehirn gelangt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Hautrötung mit Hitzegefühl (Flush)","Hautausschlag","Übelkeit, Bauchschmerzen","Gelenk-, Rücken- und Gliederschmerzen","Fieber, Reaktionen an der Infusionsstelle"],"haeufig":["Anaphylaxie (schwere allergische Reaktion)","Unruhe, Schwindel, Kribbeln","Herzrasen, Blutdruckabfall, Blässe","Atemnot, Atembeschwerden, Husten","Erbrechen, Durchfall","Angioödem (Schwellung von Gesicht oder Hals), Nesselsucht, Juckreiz","Schüttelfrost, Müdigkeit, grippeähnliche Beschwerden","Erniedrigte Sauerstoffsättigung"],"unbekannt":["Bronchospasmus (Verkrampfung der Atemwege), Kehlkopfschwellung, Atemversagen","Blauverfärbung der Haut (Zyanose)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen. Nur anwenden, wenn eindeutig nötig.","stillzeit":"Keine Daten zum Übergang in die Muttermilch; während der Behandlung wird vom Stillen abgeraten.","hinweise":["Wird wöchentlich als Infusion in eine Vene gegeben; etwa eine Stunde vorher werden meist ein Fiebermittel und ein Antihistaminikum verabreicht.","Bei Fieber oder Atemwegsinfekt vor der Infusion das Behandlungsteam informieren.","Atemnot, Schwellungen oder Ausschlag während oder nach der Infusion sofort melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"larotrectinib":{"wirkmechanismus":"Blockiert ein Wachstumssignal, das durch eine bestimmte Genveränderung im Tumor dauerhaft eingeschaltet ist. Larotrectinib ist ein hochselektiver Hemmer der Tropomyosin-Rezeptor-Kinasen TRKA, TRKB und TRKC. Bei NTRK-Genfusionen entstehen ständig aktive TRK-Fusionsproteine, die das Tumorwachstum antreiben; ihre Hemmung führt zu Wachstumsstopp und Zelltod der Tumorzellen.","nebenwirkungen":{"sehrHaeufig":["Blutarmut, Neutropenie und Leukopenie (Mangel an weissen Blutkörperchen)","Schwindel","Übelkeit, Erbrechen, Verstopfung","Muskelschmerzen","Müdigkeit","Erhöhte Leberwerte (ALT, AST)","Gewichtszunahme"],"haeufig":["Gangstörungen, Kribbeln (Parästhesien)","Geschmacksstörungen","Muskelschwäche","Erhöhte alkalische Phosphatase"],"unbekannt":["Schwere Leberschäden","Knochenbrüche"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit (keine Daten, Schädigung möglich). Frauen im gebärfähigen Alter und Männer mit Partnerin im gebärfähigen Alter müssen während der Behandlung und mindestens 1 Monat danach zuverlässig verhüten; bei hormonaler Verhütung zusätzlich eine Barrieremethode.","stillzeit":"Während der Behandlung und bis 3 Tage nach der letzten Dosis nicht stillen.","hinweise":["Zweimal täglich mit oder ohne Mahlzeit einnehmen; keine Grapefruit, kein Johanniskraut.","Schwindel und Müdigkeit können die Fahrtüchtigkeit beeinträchtigen.","Leberwerte werden regelmässig kontrolliert.","Die Lösung zum Einnehmen eignet sich für Kinder und bei Schluckbeschwerden; Dosis mit der Dosierspritze genau abmessen."],"darreichung":["Hartkapseln","Lösung zum Einnehmen"]},"latanoprost":{"wirkmechanismus":"Senkt den Augeninnendruck, indem mehr Kammerwasser aus dem Auge abfliessen kann. Latanoprost ist ein Prodrug (Isopropylester), das in der Hornhaut zur aktiven Latanoprost-Säure gespalten wird. Diese aktiviert den Prostaglandin-FP-Rezeptor und steigert vor allem den uveoskleralen Abfluss über den Ziliarmuskel. Die Drucksenkung beginnt nach 3–4 Stunden und hält mindestens 24 Stunden an.","nebenwirkungen":{"sehrHaeufig":["Zunehmende, dauerhafte Braunfärbung der Iris (Regenbogenhaut)","Leichte bis mässige Rötung der Bindehaut","Augenreizung (Brennen, Sandkorngefühl, Jucken, Stechen, Fremdkörpergefühl)","Längere, dickere, dunklere und zahlreichere Wimpern"],"haeufig":["Punktförmige Hornhautentzündung, meist ohne Beschwerden","Lidrandentzündung (Blepharitis)","Augenschmerzen, Lichtempfindlichkeit","Bindehautentzündung (Konjunktivitis)"],"gelegentlich":["Makulaödem (Schwellung der Netzhautmitte)","Uveitis (Entzündung im Augeninneren)","Lidschwellung, trockenes Auge, verschwommenes Sehen","Kopfschmerzen, Schwindel","Asthma, Atemnot","Angina pectoris (Brustenge), Herzklopfen","Übelkeit, Erbrechen","Muskel- und Gelenkschmerzen"],"selten":["Herpes-Keratitis (Hornhautentzündung durch Herpesviren)","Iritis (Entzündung der Regenbogenhaut)","Hornhautschwellung und Hornhauterosion","Schwellung um das Auge, Iriszyste","Dunkelfärbung der Lidhaut, nach innen wachsende Wimpern (Trichiasis)","Verschlechterung eines Asthmas","Juckreiz"],"sehrSelten":["Einsinken des Augenlids (Vertiefung der Lidfurche)","Verschlechterung einer Angina pectoris bei Herzkranken"]},"schwangerschaft":"Nicht anwenden: Latanoprost kann sich schädlich auf den Verlauf der Schwangerschaft und das Ungeborene auswirken.","stillzeit":"Nicht anwenden oder abstillen: Latanoprost und seine Abbauprodukte können in die Muttermilch übergehen.","hinweise":["Nicht häufiger als einmal täglich anwenden (am besten abends) – häufigere Anwendung schwächt die Drucksenkung ab.","Nach dem Eintropfen die Augen 1–2 Minuten schliessen oder den inneren Augenwinkel zudrücken.","Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen.","Xalatan ungeöffnet im Kühlschrank lagern; eine angebrochene Flasche höchstens 4 Wochen verwenden."],"darreichung":["Augentropfen","Augentropfen ohne Konservierungsmittel (Einzeldosen)"]},"latanoprost-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck über zwei sich ergänzende Wege. Latanoprost ist ein Prostaglandin-F2α-Analogon und eine Vorstufe (Prodrug), die im Auge zur wirksamen Latanoprost-Säure umgewandelt wird; diese steigert den Abfluss des Kammerwassers über den uveoskleralen Weg. Timolol, ein nicht selektiver Betablocker, vermindert die Kammerwasserbildung im Ziliarkörper. Timolol kann nach Aufnahme über die Schleimhäute auch Puls, Blutdruck und Bronchien beeinflussen.","nebenwirkungen":{"sehrHaeufig":["Dauerhafte Braunfärbung der Iris (Irispigmentierung)"],"haeufig":["Augenreizung (Brennen, Stechen, Jucken, Fremdkörpergefühl)","Augenschmerzen"],"gelegentlich":["Kopfschmerzen","Augenrötung, Bindehautentzündung, Lidrandentzündung","Verschwommenes Sehen, vermehrter Tränenfluss","Hornhautveränderungen","Hautausschlag, Juckreiz"],"unbekannt":["Veränderung der Wimpern (länger, dichter, dunkler) und dunklere Lidhaut","Makulaödem (Netzhautschwellung), Entzündung im Augeninneren (Iritis, Uveitis)","Langsamer Puls (Bradykardie), Herzrhythmusstörungen, Blutdruckabfall","Bronchospasmus, Asthma, Atemnot","Schwindel, Müdigkeit, Depression, Schlafstörungen","Verdeckte Unterzuckerung bei Diabetes","Wiederaufflammen einer Herpes-Hornhautentzündung"]},"schwangerschaft":"In der Schwangerschaft nicht anwenden: Latanoprost kann den Schwangerschaftsverlauf ungünstig beeinflussen, Timolol beim Neugeborenen Puls und Blutzucker senken.","stillzeit":"Beide Wirkstoffe können in die Muttermilch übergehen – in der Stillzeit nicht anwenden.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Ungeöffnete Fläschchen im Kühlschrank aufbewahren; nach dem Öffnen die Lagerangaben der Packung beachten.","Bei Asthma, Herzkrankheiten oder vor einer Operation die Anwendung der Augentropfen ärztlich angeben.","Bei mehreren Augenmitteln mindestens 5 Minuten Abstand einhalten."],"darreichung":["Augentropfen"]},"lavendeloel":{"wirkmechanismus":"Lindert Unruhe und Ängstlichkeit, in der Regel ohne müde zu machen. Der Lavendelöl-Spezialextrakt Silexan dämpft in Nervenzellen den Einstrom von Calcium über spannungsabhängige Calciumkanäle und verringert so die Freisetzung erregender Botenstoffe. Anders als Benzodiazepine wirkt er nicht über den GABA-A-Rezeptor; ein Abhängigkeitspotenzial ist nicht bekannt.","nebenwirkungen":{"haeufig":["Aufstossen (Eruktation), teils mit Lavendelgeschmack"],"unbekannt":["Magen-Darm-Beschwerden wie Übelkeit oder Verdauungsbeschwerden","Allergische Hautreaktionen"]},"schwangerschaft":"Keine ausreichenden Daten; in der Schwangerschaft nicht empfohlen.","stillzeit":"Nicht bekannt, ob Bestandteile in die Muttermilch übergehen; in der Stillzeit nicht empfohlen.","hinweise":["Kapsel unzerkaut mit Flüssigkeit schlucken und nicht im Liegen einnehmen (vermindert Aufstossen).","Die Wirkung setzt nicht sofort ein, sondern entwickelt sich bei regelmässiger Einnahme über einige Tage bis Wochen.","Bei anhaltenden oder zunehmenden Beschwerden ärztlichen Rat einholen."],"darreichung":["Weichkapseln"]},"lazertinib":{"wirkmechanismus":"Blockiert gezielt das veränderte Wachstumssignal-Enzym EGFR in Lungenkrebszellen. Lazertinib ist ein irreversibler EGFR-Tyrosinkinasehemmer der dritten Generation, der die aktivierenden EGFR-Mutationen (Exon-19-Deletion, L858R) und die Resistenzmutation T790M hemmt und den normalen EGFR weitgehend schont; es gelangt auch ins Gehirn. Zusammen mit dem Antikörper Amivantamab, der an EGFR und MET bindet, wird der Signalweg doppelt blockiert.","nebenwirkungen":{"sehrHaeufig":["Hautausschlag, akneähnliche Hautveränderungen, trockene Haut, Juckreiz","Paronychie (Nagelbettentzündung)","Venöse Thromboembolien (Thrombose, Lungenembolie)","Stomatitis (Mundschleimhautentzündung)","Wassereinlagerungen, tiefes Albumin im Blut","Erhöhte Leberwerte","Verstopfung, Durchfall, Übelkeit, Appetitlosigkeit","Muskelkrämpfe, Missempfindungen (Parästhesien), Müdigkeit"],"haeufig":["Interstitielle Lungenerkrankung, Pneumonitis (Lungenentzündung ohne Erreger)","Keratitis (Hornhautentzündung) und andere Augenbeschwerden"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter und Männer mit Partnerin im gebärfähigen Alter müssen während und einige Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und einige Wochen danach nicht stillen.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten einnehmen.","Haut vorbeugend mit feuchtigkeitsspendender Creme pflegen, Sonne meiden und Sonnenschutz verwenden.","Schwellung oder Schmerzen in einem Bein, plötzliche Atemnot oder Brustschmerzen sofort ärztlich abklären (Thrombose, Lungenembolie).","Neu auftretenden Husten, Atemnot oder Fieber rasch melden."],"darreichung":["Filmtabletten"]},"lebrikizumab":{"wirkmechanismus":"Dämpft die allergische Entzündung der Haut und lindert Ekzeme und Juckreiz. Lebrikizumab ist ein humanisierter IgG4-Antikörper, der mit hoher Affinität an Interleukin-13 (IL-13) bindet. Er verhindert, dass sich der Signalkomplex aus IL-4-Rezeptor-alpha und IL-13-Rezeptor-alpha-1 bildet, und unterbricht so die Signalübertragung von IL-13, einem Hauptbotenstoff der Typ-2-Entzündung bei Neurodermitis.","nebenwirkungen":{"haeufig":["Bindehautentzündung (Konjunktivitis), auch allergisch","Trockenes Auge","Reaktionen an der Injektionsstelle"],"gelegentlich":["Gürtelrose (Herpes zoster)","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Keratitis (Hornhautentzündung), Blepharitis (Lidrandentzündung)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; vorsichtshalber während der Schwangerschaft vermeiden.","stillzeit":"Nicht bekannt, ob Lebrikizumab in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Im Kühlschrank lagern; vor der Injektion auf Raumtemperatur kommen lassen.","Neu auftretende Augenrötung, Augenschmerzen oder Sehstörungen ärztlich abklären lassen.","Kortison- oder Calcineurinhemmer-Cremes können nach ärztlicher Anweisung weiter verwendet werden."],"darreichung":["Injektionslösung (Fertigpen)","Injektionslösung (Fertigspritze)"]},"ledipasvir-sofosbuvir":{"wirkmechanismus":"Hemmt die Vermehrung des Hepatitis-C-Virus an zwei Stellen. Ledipasvir blockiert das virale Protein NS5A, das für die Vervielfältigung des Virus-Erbguts und den Zusammenbau neuer Viren nötig ist. Sofosbuvir wird in der Leber zu einem Nukleotid-Analogon aktiviert, das die virale RNA-Polymerase NS5B hemmt und zum Kettenabbruch führt. Ledipasvir hemmt zudem die Transporter P-Glykoprotein und BCRP im Darm und erhöht so die Aufnahme mancher anderer Arzneimittel.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Müdigkeit"],"haeufig":["Hautausschlag"],"unbekannt":["Angioödem (Schwellung von Haut und Schleimhäuten)","Stevens-Johnson-Syndrom","Schwere Bradykardie bei gleichzeitiger Amiodaron-Einnahme","Reaktivierung einer Hepatitis B"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; vorsichtshalber in der Schwangerschaft nicht anwenden. In Kombination mit Ribavirin kontraindiziert.","stillzeit":"Nicht stillen; der Übergang in die Muttermilch ist beim Menschen nicht bekannt, im Tierversuch wurden die Wirkstoffe in der Milch nachgewiesen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen; die verordnete Therapiedauer genau einhalten.","Säurebinder und Magenschutzmittel nur nach Rücksprache und mit dem empfohlenen Zeitabstand einnehmen.","Bei langsamem Puls, Schwindel oder Ohnmacht (v. a. unter Amiodaron) sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"leflunomid":{"wirkmechanismus":"Bremst die Vermehrung von Abwehrzellen, welche die Gelenkentzündung unterhalten. Leflunomid ist ein Prodrug und wird rasch zum Wirkmetaboliten Teriflunomid umgewandelt. Dieser hemmt das Enzym Dihydroorotat-Dehydrogenase (DHODH) und damit die Neubildung von Pyrimidin-Bausteinen, die aktivierte Lymphozyten zur Teilung brauchen. Teriflunomid wird sehr langsam ausgeschieden (Halbwertszeit etwa 2 Wochen) und kann monate- bis jahrelang im Blut bleiben.","nebenwirkungen":{"haeufig":["Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Mundschleimhautentzündung","Erhöhte Leberwerte","Leichter Blutdruckanstieg","Leukopenie (Mangel an weissen Blutkörperchen)","Kopfschmerzen, Schwindel, Parästhesien (Kribbeln), periphere Neuropathie (Nervenschädigung)","Haarausfall, Ekzem, Ausschlag, Juckreiz, trockene Haut","Sehnenscheidenentzündung, erhöhte Kreatinkinase","Appetitlosigkeit, Gewichtsverlust, Schwäche, leichte allergische Reaktionen"],"gelegentlich":["Anämie, Thrombozytopenie","Kaliummangel, erhöhte Blutfette, Phosphatmangel","Geschmacksstörungen, Angst","Nesselsucht","Sehnenriss"],"selten":["Schwere Infektionen inkl. Sepsis","Panzytopenie, Eosinophilie","Hepatitis, Gelbsucht","Interstitielle Lungenerkrankung"],"sehrSelten":["Agranulozytose","Schwere Leberschäden bis Leberversagen","Pankreatitis","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme","Anaphylaxie, Vaskulitis"],"unbekannt":["DRESS (schwere Arzneimittelreaktion mit Hautausschlag und Organbeteiligung)","Pulmonale Hypertonie (Lungenhochdruck)","Nierenversagen","Kutaner Lupus erythematodes, pustulöse Psoriasis","Kolitis (Darmentzündung)"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend). Vor einer geplanten Schwangerschaft muss der Wirkstoff mit einem Auswaschverfahren (Colestyramin oder Aktivkohle) entfernt und der Spiegel zweimal kontrolliert werden; sonst dauert es bis zu 2 Jahre.","stillzeit":"Kontraindiziert; nicht stillen.","hinweise":["Leberwerte, Blutbild und Blutdruck werden zu Beginn alle 2 Wochen, später regelmässig kontrolliert.","Alkohol möglichst meiden (Leber).","Bei Kinderwunsch (Frauen und Männer) frühzeitig ärztlich besprechen: Auswaschverfahren nötig.","Bei Husten mit Atemnot, Fieber oder schweren Hautreaktionen sofort ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"lenacapavir":{"wirkmechanismus":"Greift die Eiweisshülle (Kapsid) des HI-Virus an, die das Erbgut des Virus umschliesst. Lenacapavir bindet zwischen benachbarte Kapsid-Proteinuntereinheiten (p24) und stört dadurch mehrere Schritte des Vermehrungszyklus: den Transport des Virus-Erbguts in den Zellkern, den Zusammenbau neuer Viren und die korrekte Bildung des Kapsids. Weil der Wirkstoff aus dem Unterhautgewebe sehr langsam freigesetzt wird, reicht nach der Aufsättigung eine Injektion alle 6 Monate.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Einstichstelle (Schwellung, Schmerz, Rötung, Knötchen, Verhärtung)"],"haeufig":["Übelkeit"],"unbekannt":["Immunrekonstitutions-Syndrom (Entzündungsreaktionen bei Therapiebeginn)"]},"schwangerschaft":"Nur wenige Daten beim Menschen. Vorsichtshalber in der Schwangerschaft möglichst vermeiden, ausser der Gesundheitszustand erfordert die Behandlung; die lange Verweildauer im Körper beachten.","stillzeit":"Frauen mit HIV wird in der Regel vom Stillen abgeraten; das Vorgehen mit der behandelnden Fachperson besprechen.","hinweise":["Injektionstermine (alle 6 Monate) genau einhalten – verpasste Termine können zu Resistenzen führen.","Lenacapavir bleibt nach der letzten Spritze noch viele Monate im Körper: bei jeder neuen Behandlung Ärztin, Arzt oder Apotheke darauf hinweisen.","Knötchen an der Einstichstelle sind häufig und bilden sich meist langsam zurück."],"darreichung":["Filmtabletten","Injektionslösung (unter die Haut)"]},"lenalidomid":{"wirkmechanismus":"Stärkt die körpereigene Abwehr gegen Krebszellen und hemmt deren Wachstum. Lenalidomid bindet an das Protein Cereblon, einen Teil eines Ubiquitin-Ligase-Komplexes, und bewirkt so den Abbau der Transkriptionsfaktoren Ikaros und Aiolos (bei MDS mit Deletion 5q zusätzlich der Casein-Kinase 1α). Daraus folgen ein direkter Zelltod von Myelom- und Lymphomzellen, eine Aktivierung von T- und NK-Zellen sowie eine Hemmung der Gefässneubildung im Tumor.","nebenwirkungen":{"sehrHaeufig":["Neutropenie (Mangel an weissen Blutkörperchen)","Thrombozytopenie (Mangel an Blutplättchen)","Anämie (Blutarmut)","Infektionen, z. B. Lungenentzündung und Atemwegsinfekte","Durchfall, Verstopfung, Übelkeit","Muskelkrämpfe","Müdigkeit (Fatigue)","Hautausschlag"],"haeufig":["Tiefe Venenthrombose und Lungenembolie","Fieber bei Neutropenie (febrile Neutropenie) und Sepsis (Blutvergiftung)","Herzinfarkt, Vorhofflimmern, Herzinsuffizienz","Akutes Nierenversagen","Periphere Neuropathie (Nervenschädigung mit Kribbeln oder Taubheit)","Schilddrüsenunterfunktion","Zweittumoren (z. B. weisser Hautkrebs, akute myeloische Leukämie)"],"gelegentlich":["Tumorlyse-Syndrom (Stoffwechselentgleisung durch rasch zerfallende Tumorzellen)","Angioödem (Schwellung von Haut und Schleimhaut)"],"selten":["Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautreaktionen)","Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["DRESS (Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)","Reaktivierung einer Hepatitis B","Akutes Leberversagen, Hepatitis","Abstossung transplantierter Organe","Progressive multifokale Leukenzephalopathie (PML, Virusinfektion des Gehirns)"]},"schwangerschaft":"Kontraindiziert. Lenalidomid ist mit Thalidomid verwandt und kann schwere Fehlbildungen verursachen; Frauen im gebärfähigen Alter dürfen es nur im Rahmen des Schwangerschaftsverhütungsprogramms mit zuverlässiger Verhütung und regelmässigen Schwangerschaftstests einnehmen.","stillzeit":"Nicht stillen: Es ist unbekannt, ob Lenalidomid in die Muttermilch übergeht; während der Behandlung muss abgestillt werden.","hinweise":["Frauen im gebärfähigen Alter verhüten zuverlässig ab 4 Wochen vor bis 4 Wochen nach der Behandlung; Männer verwenden während der Behandlung und bis 1 Woche danach Kondome (auch nach Vasektomie).","Kapseln unzerkaut schlucken, nicht öffnen und nicht weitergeben; nicht gebrauchte Kapseln in der Apotheke zurückgeben. Während der Behandlung und bis 1 Woche danach kein Blut und keinen Samen spenden.","Regelmässige Blutbildkontrollen. Bei Fieber, Infektzeichen, Atemnot, Brustschmerzen oder einem geschwollenen, schmerzhaften Bein sofort ärztliche Hilfe holen.","Müdigkeit, Schwindel und verschwommenes Sehen sind möglich – Vorsicht beim Autofahren."],"darreichung":["Hartkapseln"]},"lenograstim":{"wirkmechanismus":"Regt das Knochenmark an, mehr neutrophile Granulozyten (weisse Blutkörperchen zur Infektabwehr) zu bilden. Lenograstim ist ein gentechnisch in Säugetierzellen hergestellter, glykosylierter humaner G-CSF, der an G-CSF-Rezeptoren der Vorläuferzellen bindet. Er fördert deren Vermehrung, Ausreifung und Freisetzung ins Blut und verbessert die Funktion der Neutrophilen. Ausserdem schwemmt er Blutstammzellen aus dem Knochenmark ins Blut aus, wo sie für eine Transplantation gesammelt werden können.","nebenwirkungen":{"sehrHaeufig":["Knochen-, Rücken- und Muskelschmerzen","Kopfschmerzen, Schwäche","Reaktionen an der Einstichstelle","Leukozytose (Anstieg der weissen Blutkörperchen), Thrombozytopenie","Erhöhte LDH (Laborwert)"],"haeufig":["Milzvergrösserung","Bauchschmerzen","Erhöhte Leberwerte und alkalische Phosphatase"],"selten":["Milzriss","Lungenkomplikationen (Lungenödem, interstitielle Pneumonie, Lungeninfiltrate, Lungenfibrose)","Anaphylaxie","Hautreaktionen wie Sweet-Syndrom, Erythema nodosum, Pyoderma gangraenosum","Toxische epidermale Nekrolyse (Lyell-Syndrom)"],"unbekannt":["Kapillarlecksyndrom","Glomerulonephritis (Nierenentzündung)","Aortitis (Entzündung der Hauptschlagader)","Sichelzellkrisen bei Sichelzellkrankheit"]},"schwangerschaft":"Nur nach strenger Nutzen-Risiko-Abwägung (keine ausreichenden Erfahrungen).","stillzeit":"Während der Behandlung nicht stillen (Übergang in die Muttermilch nicht bekannt).","hinweise":["Nicht im Zeitraum von 24 Stunden vor bis 24 Stunden nach einer Chemotherapie spritzen.","Schmerzen im linken Oberbauch oder in der Schulterspitze, Atemnot oder Husten mit Fieber sofort melden.","Knochenschmerzen sind häufig und lassen sich meist mit einfachen Schmerzmitteln wie Paracetamol lindern.","Das Blutbild wird regelmässig kontrolliert."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektions- oder Infusionslösung"]},"lenvatinib":{"wirkmechanismus":"Hemmt die Bildung neuer Blutgefässe im Tumor und Wachstumssignale der Krebszellen. Lenvatinib blockiert die Rezeptor-Tyrosinkinasen VEGFR-1 bis -3, FGFR-1 bis -4, PDGFR-α sowie KIT und RET. Durch die zusätzliche FGFR-Hemmung unterscheidet es sich von anderen VEGF-Hemmern. Bei Nieren- und Gebärmutterschleimhautkrebs wird es mit dem Immuntherapeutikum Pembrolizumab bzw. mit Everolimus kombiniert.","nebenwirkungen":{"sehrHaeufig":["Bluthochdruck","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung","Appetitverlust, Gewichtsabnahme, Müdigkeit, Schwäche","Stomatitis, Mundtrockenheit, Geschmacksstörungen, Heiserkeit","Eiweiss im Urin (Proteinurie)","Hypothyreose (Schilddrüsenunterfunktion)","Hand-Fuss-Syndrom, Hautausschlag, Haarausfall","Blutungen (z. B. Nasenbluten), Mangel an Blutplättchen, Kopfschmerzen, Gelenk- und Muskelschmerzen"],"haeufig":["Herzinsuffizienz, Herzinfarkt, Abnahme der Herzpumpfunktion","QT-Verlängerung im EKG","Schlaganfall, Lungenembolie","Leberversagen, hepatische Enzephalopathie (v. a. bei Leberzellkrebs)","Nierenversagen, Flüssigkeitsmangel","Tiefes Calcium, Kalium und Magnesium","Analfisteln"],"gelegentlich":["Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Transitorische ischämische Attacke (TIA)","Kiefernekrose (Absterben von Kieferknochen)","Nephrotisches Syndrom","Wundheilungsstörungen","Milzinfarkt"],"unbekannt":["Magen-Darm-Durchbruch (Perforation) und Fisteln","Pankreatitis (Bauchspeicheldrüsenentzündung)","Aneurysmen und Gefässwandeinrisse (Dissektionen)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit – kann das ungeborene Kind schädigen. Frauen müssen während der Behandlung und bis 1 Monat danach hochwirksam verhüten; bei hormonaler Verhütung zusätzlich eine Barrieremethode.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit mit oder ohne Mahlzeit; Kapseln unzerkaut schlucken oder in wenig Wasser bzw. Apfelsaft auflösen.","Blutdruck regelmässig messen; Urin (Eiweiss), Leber- und Schilddrüsenwerte werden regelmässig kontrolliert.","Durchfall früh behandeln und genug trinken, um Nierenschäden durch Flüssigkeitsverlust zu vermeiden.","Vor Operationen und Zahnbehandlungen nach ärztlicher Anweisung pausieren."],"darreichung":["Hartkapseln"]},"lercanidipin":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Muskulatur der Arterien entspannt. Lercanidipin blockiert sehr gefässselektiv die L-Typ-Calciumkanäle der glatten Gefässmuskulatur und senkt so den peripheren Widerstand, ohne die Herzkraft wesentlich zu beeinflussen. Weil sich der stark fettlösliche Wirkstoff in den Zellmembranen anreichert, hält die Wirkung trotz kurzer Plasmahalbwertszeit 24 Stunden an. Der Abbau erfolgt fast vollständig über CYP3A4, deshalb reagieren die Spiegel stark auf Hemmer dieses Enzyms.","nebenwirkungen":{"gelegentlich":["Kopfschmerzen","Schwindel","Herzklopfen, beschleunigter Puls (Tachykardie)","Flush (Gesichtsrötung mit Wärmegefühl)","Periphere Ödeme (Wassereinlagerungen, vor allem an den Knöcheln)"],"selten":["Schläfrigkeit","Angina pectoris (Brustenge)","Übelkeit, Verdauungsstörungen, Durchfall, Bauchschmerzen, Erbrechen","Hautausschlag, Juckreiz","Muskelschmerzen","Vermehrtes Wasserlassen (Polyurie)","Schwäche, Müdigkeit","Überempfindlichkeitsreaktionen"],"sehrSelten":["Hypotonie (tiefer Blutdruck)"],"unbekannt":["Synkope (Ohnmacht)","Zahnfleischwucherung (Gingivahyperplasie)","Erhöhte Leberwerte","Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Trübes Dialysat bei Peritonealdialyse"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter dürfen Lercanidipin nur mit zuverlässiger Verhütung einnehmen.","stillzeit":"Kontraindiziert.","hinweise":["Mindestens 15 Minuten vor einer Mahlzeit, am besten morgens, mit Wasser einnehmen – fettreiches Essen erhöht die Aufnahme stark.","Kein Grapefruitsaft und möglichst kein Alkohol.","Schwindel oder Müdigkeit möglich – Vorsicht beim Autofahren."],"darreichung":["Filmtabletten"]},"letermovir":{"wirkmechanismus":"Verhindert, dass sich das Zytomegalievirus in den Zellen vermehren kann. Letermovir hemmt den viralen DNA-Terminase-Komplex (Untereinheiten pUL51, pUL56 und pUL89), der die neu gebildete Virus-DNA in einzelne Genome zerschneidet und in die Viruskapside verpackt. Ohne diesen Schritt entstehen keine infektiösen Viruspartikel. Letermovir wirkt spezifisch gegen CMV, nicht gegen andere Herpesviren, und schädigt das Knochenmark nicht.","nebenwirkungen":{"haeufig":["Übelkeit","Durchfall","Erbrechen"],"gelegentlich":["Überempfindlichkeitsreaktionen","Appetitlosigkeit, Geschmacksstörungen","Kopfschmerzen, Drehschwindel (Vertigo)","Bauchschmerzen","Erhöhte Leberwerte (ALT, AST)","Muskelkrämpfe","Erhöhtes Kreatinin im Blut","Müdigkeit, periphere Ödeme (Wassereinlagerungen in den Beinen)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; Tierversuche zeigten eine Reproduktionstoxizität. Anwendung in der Schwangerschaft und bei Frauen im gebärfähigen Alter ohne Verhütung nicht empfohlen.","stillzeit":"Letermovir geht bei Tieren in die Milch über; ein Risiko für das Kind kann nicht ausgeschlossen werden. Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Tabletten mit oder ohne Mahlzeit einnehmen; die Infusion ist für Personen gedacht, die keine Tabletten einnehmen können.","Beim Beginn oder Absetzen von Letermovir müssen die Spiegel von Ciclosporin, Tacrolimus oder Sirolimus kontrolliert werden.","Auch nach Ende der Vorbeugung CMV nach Anweisung des Transplantationszentrums kontrollieren lassen.","Vor der Einnahme weiterer Medikamente, auch pflanzlicher wie Johanniskraut, ärztlich oder in der Apotheke nachfragen."],"darreichung":["Filmtabletten","Konzentrat zur Herstellung einer Infusionslösung"]},"letrozol":{"wirkmechanismus":"Senkt den Östrogenspiegel nach den Wechseljahren stark, sodass hormonabhängige Tumoren nicht mehr angeregt werden. Letrozol hemmt selektiv und kompetitiv die Aromatase (CYP19), die im Fett- und Muskelgewebe Androgene in Östrogene umwandelt. Dadurch sinken die Östrogenspiegel um über 75 %. Die Bildung von Kortison und Aldosteron wird nicht beeinflusst.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Gelenkschmerzen","Erhöhtes Cholesterin","Müdigkeit","Vermehrtes Schwitzen"],"haeufig":["Kopfschmerzen, Schwindel","Depression","Übelkeit, Durchfall, Verstopfung","Haarausfall, Hautausschlag","Muskel- und Knochenschmerzen","Osteoporose, Knochenbrüche","Gewichtszunahme, gesteigerter Appetit","Bluthochdruck, Scheidenblutungen"],"gelegentlich":["Thrombophlebitis (Venenentzündung, auch tiefe Venen)","Schlaganfall","Grauer Star (Katarakt)","Karpaltunnelsyndrom","Schnellender Finger","Herzklopfen, Herzrasen, ischämische Herzereignisse (z. B. Angina pectoris)","Erhöhte Leberwerte, Gelbsucht"],"selten":["Lungenembolie","Arterielle Thrombose"],"unbekannt":["Anaphylaxie, Angioödem","Hepatitis","Toxische epidermale Nekrolyse, Erythema multiforme"]},"schwangerschaft":"Kontraindiziert. Bei Frauen kurz nach der Menopause kann die Eierstockfunktion zurückkehren – bis zur gesicherten Postmenopause verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Täglich zur gleichen Zeit einnehmen, mit oder ohne Essen.","Knochendichte regelmässig messen; ausreichend Calcium, Vitamin D und Bewegung.","Müdigkeit und Schwindel können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"leuprorelin":{"wirkmechanismus":"Schaltet über die Hirnanhangsdrüse die Bildung von Geschlechtshormonen ab. Leuprorelin ist ein synthetisches Analogon des Hypothalamushormons GnRH. Zu Beginn steigen LH, FSH und damit Testosteron bzw. Östrogen kurzzeitig an («Flare»); die Dauerstimulation führt dann zu einer Abnahme der GnRH-Rezeptoren in der Hypophyse. Nach 2–4 Wochen sinken die Hormonspiegel auf Kastrationsniveau, solange die Behandlung fortgeführt wird.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Reaktionen an der Injektionsstelle (Brennen, Rötung, Schmerzen)","Müdigkeit"],"haeufig":["Libidoverlust, Erektionsstörungen, Hodenverkleinerung","Gynäkomastie (Brustvergrösserung beim Mann)","Vermehrtes Schwitzen","Gelenk- und Muskelschmerzen","Kopfschmerzen, Schwindel","Übelkeit, Durchfall","Scheidentrockenheit (bei Frauen)","Schlafstörungen, Stimmungsschwankungen"],"gelegentlich":["Depression","Gewichtsveränderungen","Erhöhte Blutzucker- und Leberwerte"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Hypophysenapoplexie (Einblutung in einen Hypophysentumor)"],"unbekannt":["Abnahme der Knochendichte, Osteoporose","QT-Verlängerung","Krampfanfälle","Interstitielle Lungenerkrankung","Idiopathische intrakranielle Hypertension (Hirndrucksteigerung)"]},"schwangerschaft":"Kontraindiziert. Vor Behandlungsbeginn Schwangerschaft ausschliessen; während der Behandlung eine nicht hormonelle Verhütungsmethode anwenden (z. B. Kondom).","stillzeit":"Kontraindiziert.","hinweise":["In den ersten Wochen können Beschwerden vorübergehend zunehmen (Flare) – Knochenschmerzen oder Probleme beim Wasserlösen melden.","Bei Langzeitbehandlung Knochendichte, Blutzucker und Blutfette kontrollieren; auf Calcium und Vitamin D achten.","Termine für die Depotspritze genau einhalten."],"darreichung":["Depot-Injektionssuspension (Fertigspritze)","Pulver und Lösungsmittel zur Herstellung einer Depot-Injektion"]},"levetiracetam":{"wirkmechanismus":"Stabilisiert die Signalübertragung zwischen Nervenzellen und verhindert so Krampfanfälle. Levetiracetam bindet an das synaptische Vesikelprotein SV2A, das an der Freisetzung von Botenstoffen beteiligt ist, und hemmt zudem N-Typ-Calciumkanäle. Es wird kaum in der Leber verstoffwechselt und überwiegend über die Nieren ausgeschieden, daher gibt es nur wenige Wechselwirkungen.","nebenwirkungen":{"sehrHaeufig":["Nasen-Rachen-Entzündung","Schläfrigkeit, Kopfschmerzen"],"haeufig":["Appetitlosigkeit","Depression, Feindseligkeit, Aggression, Angst, Schlaflosigkeit, Nervosität, Reizbarkeit","Krampfanfälle, Gleichgewichtsstörungen, Schwindel, Lethargie, Zittern","Drehschwindel (Vertigo), Husten","Bauchschmerzen, Durchfall, Verdauungsbeschwerden, Erbrechen, Übelkeit","Hautausschlag","Schwäche, Müdigkeit"],"gelegentlich":["Thrombozytopenie, Leukopenie","Suizidgedanken und -versuche, Psychose, Halluzinationen, Verhaltensstörungen, Verwirrtheit, Panikattacken","Gedächtnis- und Koordinationsstörungen, Kribbeln, Konzentrationsstörungen","Doppelbilder, verschwommenes Sehen","Erhöhte Leberwerte","Haarausfall, Ekzem, Juckreiz","Muskelschwäche, Muskelschmerzen, Gewichtsveränderung"],"selten":["Panzytopenie, Neutropenie, Agranulozytose","Überempfindlichkeitsreaktionen mit Angioödem oder Anaphylaxie, Multiorgan-Überempfindlichkeitsreaktion (DRESS)","Suizid, Persönlichkeitsveränderungen, Delir, Enzephalopathie","Bewegungsstörungen (Choreoathetose, Dyskinesie), malignes neuroleptisches Syndrom","QT-Verlängerung im EKG","Pankreatitis, Hepatitis, Leberversagen, akute Nierenschädigung","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme","Hyponatriämie (Natriummangel), Rhabdomyolyse (Muskelzerfall)"],"sehrSelten":["Zwangsstörung"]},"schwangerschaft":"Daten aus Registern zeigen kein wesentlich erhöhtes Fehlbildungsrisiko; Anwendung nach ärztlicher Abwägung möglich. Die Spiegel können in der Schwangerschaft sinken – Kontrollen; nicht eigenmächtig absetzen.","stillzeit":"Geht in die Muttermilch über; Stillen wird nicht empfohlen bzw. nur nach ärztlicher Abwägung unter Beobachtung des Kindes.","hinweise":["Nicht abrupt absetzen – Gefahr von Krampfanfällen; schrittweise nach ärztlicher Anweisung reduzieren.","Stimmungsveränderungen, Aggressivität oder Suizidgedanken sofort ärztlich melden – auch Angehörige sollen darauf achten.","Kann unabhängig von den Mahlzeiten eingenommen werden; Alkohol meiden, Vorsicht beim Autofahren."],"darreichung":["Filmtabletten","Lösung zum Einnehmen","Infusionskonzentrat bzw. Infusionslösung"]},"levobupivacain":{"wirkmechanismus":"Betäubt die Nerven im behandelten Gebiet über viele Stunden, sodass keine Schmerzen weitergeleitet werden. Levobupivacain ist die linksdrehende Form (S-Enantiomer) von Bupivacain und blockiert spannungsabhängige Natriumkanäle der Nervenmembran. Bei vergleichbarer Wirkung ist es in Tierversuchen weniger herz- und nervenschädigend als das Gemisch Bupivacain. Der Abbau erfolgt in der Leber, vor allem über CYP3A4 und CYP1A2.","nebenwirkungen":{"sehrHaeufig":["Hypotonie (Blutdruckabfall)","Übelkeit","Anämie (Blutarmut)"],"haeufig":["Schwindel","Kopfschmerzen","Erbrechen","Rückenschmerzen","Fieber","Beeinträchtigung des Kindes unter der Geburt (fetaler Distress)"],"unbekannt":["Allergische Reaktionen bis Anaphylaxie","Zeichen einer Überdosierung: Taubheit um den Mund, Ohrensausen, Sehstörungen, Krampfanfälle","Bradykardie (langsamer Puls), Herzrhythmusstörungen, Herzstillstand","Nervenschäden, Lähmungen, Cauda-equina-Syndrom nach rückenmarksnaher Gabe","Horner-Syndrom (hängendes Lid, enge Pupille)","Atemdepression bei hoher Ausbreitung der Betäubung"]},"schwangerschaft":"Für die Epiduralanalgesie unter der Geburt und den Kaiserschnitt zugelassen; in der Frühschwangerschaft nur, wenn klar notwendig. Parazervikalblockade kontraindiziert.","stillzeit":"Es gelangen nur sehr geringe Mengen in die Muttermilch; Stillen nach einer Betäubung ist möglich.","hinweise":["Wird nur von Fachpersonen mit Notfallausrüstung angewendet; Kreislauf und Bewusstsein werden überwacht.","Gefühl und Kraft können im betäubten Körperteil mehrere Stunden fehlen – nicht ohne Hilfe aufstehen und nicht Auto fahren.","Blutverdünner vor einer rückenmarksnahen Betäubung unbedingt angeben."],"darreichung":["Injektionslösung","Infusionslösung"]},"levocabastin":{"wirkmechanismus":"Blockiert am Ort der Anwendung die Wirkung von Histamin und lindert so allergische Beschwerden in Nase und Augen. Levocabastin ist ein hochwirksamer, selektiver Histamin-H1-Rezeptor-Antagonist. Die Wirkung tritt innert Minuten ein und hält mehrere Stunden an. Nur ein kleiner Teil gelangt in den Blutkreislauf; er wird grösstenteils unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (Nasenspray)"],"haeufig":["Brennen, Stechen oder Unbehagen an der Anwendungsstelle (Nase, Auge)","Nasenbluten","Schläfrigkeit, Müdigkeit","Schwindel","Augenschmerzen, verschwommenes Sehen","Rachenschmerzen, Husten, Nasennebenhöhlenentzündung","Übelkeit"],"gelegentlich":["Lidschwellung"],"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie und Angioödem"]},"schwangerschaft":"Nur nach ärztlicher Abwägung (im Tierversuch bei sehr hohen Dosen fruchtschädigend).","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nur nach ärztlicher Rücksprache.","hinweise":["Vor jedem Gebrauch gut schütteln (Suspension).","Bei Heuschnupfen regelmässig während der ganzen Belastungszeit anwenden."],"darreichung":["Nasenspray (Suspension)","Augentropfen (Suspension)"]},"levocarnitin":{"wirkmechanismus":"Hilft den Körperzellen, Fett zur Energiegewinnung zu nutzen, und unterstützt die Ausscheidung schädlicher Stoffwechselprodukte. Levocarnitin ist ein körpereigener Stoff, der langkettige Fettsäuren als Acylcarnitin durch die innere Mitochondrienmembran schleust, wo sie in der Beta-Oxidation abgebaut werden. Bei Organoazidurien bindet es zudem angehäufte, giftige Acylreste und ermöglicht deren Ausscheidung als Acylcarnitine über den Urin. So wird vor allem der Energiestoffwechsel von Herz- und Skelettmuskel wiederhergestellt.","nebenwirkungen":{"unbekannt":["Übelkeit, Erbrechen","Bauchkrämpfe, Durchfall","Fischartiger Körpergeruch"]},"schwangerschaft":"Keine ausreichenden Daten; Anwendung nur nach ärztlicher Abwägung. Bei angeborenem Carnitinmangel kann ein Absetzen schädlicher sein als die Fortführung.","stillzeit":"Carnitin ist ein natürlicher Bestandteil der Muttermilch; Anwendung in der Stillzeit nach ärztlicher Abwägung.","hinweise":["Lösung und Kautabletten zu oder nach den Mahlzeiten und über den Tag verteilt einnehmen – das verbessert die Magen-Darm-Verträglichkeit.","Fischartiger Körpergeruch oder Magen-Darm-Beschwerden bessern sich oft nach einer Dosisanpassung – mit der Ärztin oder dem Arzt besprechen.","Bei Diabetes den Blutzucker, unter Vitamin-K-Antagonisten den INR regelmässig kontrollieren.","Carnitin aus Nahrungsergänzungsmitteln ersetzt die ärztlich verordnete Behandlung nicht."],"darreichung":["Lösung zum Einnehmen","Kautabletten","Injektionslösung"]},"levocetirizin":{"wirkmechanismus":"Blockiert die Wirkung von Histamin, dem wichtigsten Botenstoff allergischer Beschwerden wie Niesen, Fliessschnupfen, Juckreiz und Quaddeln. Levocetirizin ist das wirksame R-Enantiomer von Cetirizin und bindet etwa doppelt so stark an periphere Histamin-H1-Rezeptoren. Es überwindet die Blut-Hirn-Schranke kaum und wirkt praktisch nicht anticholinerg. Es wird überwiegend unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schläfrigkeit (Somnolenz)","Mundtrockenheit","Müdigkeit"],"gelegentlich":["Schwäche (Asthenie)","Bauchschmerzen"],"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie","Unruhe, Aggressivität, Halluzinationen, Depression, Schlaflosigkeit, Suizidgedanken","Krampfanfälle, Kribbeln, Schwindel, Zittern, Ohnmacht","Herzklopfen, Herzrasen","Hepatitis (Leberentzündung) und abweichende Leberwerte","Angioödem (Schwellung von Haut und Schleimhäuten), Nesselsucht, fixes Arzneimittelexanthem","Harnverhalt, schmerzhaftes Wasserlassen","Juckreiz nach dem Absetzen"]},"schwangerschaft":"Daten zu Levocetirizin und Cetirizin zeigen kein erhöhtes Fehlbildungsrisiko; trotzdem nur nach ärztlicher Abwägung anwenden.","stillzeit":"Geht in die Muttermilch über. Nur nach ärztlicher Abwägung anwenden und beim Säugling auf Schläfrigkeit achten.","hinweise":["Kann trotz geringer Sedierung die Reaktionsfähigkeit beeinträchtigen – die eigene Reaktion vor dem Autofahren prüfen; Alkohol meiden.","Vor Allergie-Hauttests einige Tage absetzen (Rücksprache mit der Ärztin oder dem Arzt).","Bei eingeschränkter Nierenfunktion ist ein längerer Einnahmeabstand nötig."],"darreichung":["Filmtabletten"]},"levodopa-benserazid":{"wirkmechanismus":"Ersetzt den bei Parkinson fehlenden Botenstoff Dopamin im Gehirn und verbessert so die Beweglichkeit. Levodopa gelangt als Vorstufe über die Blut-Hirn-Schranke und wird im Gehirn durch die Dopa-Decarboxylase zu Dopamin umgewandelt. Benserazid hemmt dieses Enzym nur ausserhalb des Gehirns: So erreicht mehr Levodopa das Gehirn, und Nebenwirkungen wie Übelkeit und Kreislaufbeschwerden durch Dopamin im übrigen Körper nehmen ab.","nebenwirkungen":{"unbekannt":["Appetitlosigkeit, Übelkeit, Erbrechen, Durchfall, Geschmacksstörungen","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie), Herzrhythmusstörungen","Unwillkürliche Bewegungen (Dyskinesien) und Wirkungsschwankungen (On-off-Phänomen)","Plötzliche Einschlafattacken, Tagesschläfrigkeit","Impulskontrollstörungen (Spielsucht, Kaufsucht, Hypersexualität), Dopamin-Dysregulationssyndrom","Halluzinationen, Verwirrtheit, Depression, Unruhe, Schlafstörungen","Blutbildveränderungen (hämolytische Anämie, Leukopenie, Thrombozytopenie)","Erhöhte Leberwerte, Verfärbung von Urin und Schweiss"]},"schwangerschaft":"Kontraindiziert: Benserazid führte im Tierversuch zu Skelettfehlbildungen. Frauen im gebärfähigen Alter müssen zuverlässig verhüten.","stillzeit":"Nicht stillen: Levodopa hemmt die Milchbildung, und schädliche Wirkungen auf das Kind sind nicht ausgeschlossen.","hinweise":["Möglichst 30 Minuten vor oder 1 Stunde nach einer Mahlzeit einnehmen; eiweissreiche Mahlzeiten können die Wirkung abschwächen. Retardkapseln nicht öffnen oder zerkauen.","Nie abrupt absetzen – Gefahr einer lebensbedrohlichen Krise mit Fieber und Muskelstarre (malignes neuroleptisches Syndrom).","Plötzliches Einschlafen oder Kontrollverlust bei Spielen, Einkaufen oder Sexualität ärztlich melden; dann kein Auto fahren.","Urin, Schweiss und Speichel können sich dunkel verfärben – das ist harmlos."],"darreichung":["Kapseln","Tabletten","Lösliche Tabletten","Retardkapseln","Retardtabletten"]},"levodopa-carbidopa":{"wirkmechanismus":"Ersetzt den bei Parkinson fehlenden Botenstoff Dopamin im Gehirn. Levodopa ist eine Vorstufe von Dopamin, die – anders als Dopamin selbst – die Blut-Hirn-Schranke überwindet und im Gehirn durch die Dopa-Decarboxylase zu Dopamin umgewandelt wird. Carbidopa hemmt dieses Enzym ausserhalb des Gehirns, gelangt selbst aber nicht ins Gehirn. Dadurch erreicht mehr Levodopa das Gehirn, die nötige Dosis sinkt und Nebenwirkungen wie Übelkeit und Kreislaufbeschwerden werden geringer.","nebenwirkungen":{"sehrHaeufig":["Dyskinesien (unwillkürliche Überbewegungen)","Übelkeit","Duodopa: Bauchschmerzen und Komplikationen durch Sonde und Eingriff (z. B. Wundinfektion)"],"haeufig":["Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Schwindel","Herzklopfen, unregelmässiger Herzschlag","Halluzinationen, Verwirrtheit, abnorme Träume","Schlaflosigkeit, Schläfrigkeit, plötzliches Einschlafen","Depression, Angst","Erbrechen, Verstopfung, Mundtrockenheit, Appetitlosigkeit, Gewichtsabnahme","Wirkungsschwankungen (On-off-Phänomene)","Duodopa: Polyneuropathie (Nervenschädigung), Vitamin-B6- und -B12-Mangel"],"gelegentlich":["Dunkelfärbung von Urin, Schweiss oder Speichel (harmlos)","Verminderung der weissen Blutkörperchen oder der Blutplättchen","Krampfanfälle","Verschwommenes Sehen"],"selten":["Agranulozytose (starker Mangel an weissen Blutkörperchen)","Angioödem, Nesselsucht","Magen-Darm-Blutungen, Zwölffingerdarmgeschwür","Priapismus (schmerzhafte Dauererektion)"],"unbekannt":["Impulskontrollstörungen (Spielsucht, Kaufsucht, Essattacken, gesteigertes sexuelles Verlangen)","Dopamin-Dysregulationssyndrom (zwanghafte Übereinnahme)","Malignes Melanom (schwarzer Hautkrebs)","Hämolytische Anämie (Blutzerfall)","Lebensbedrohliches Fieber mit Muskelsteife und Bewusstseinsstörung bei abruptem Absetzen (ähnlich dem malignen neuroleptischen Syndrom)"]},"schwangerschaft":"Erfahrungen beim Menschen sind begrenzt; im Tierversuch traten Fehlbildungen auf. Nur anwenden, wenn der Nutzen das Risiko für das Kind klar überwiegt.","stillzeit":"Levodopa geht in die Muttermilch über und kann die Milchbildung hemmen. Während der Behandlung nicht stillen.","hinweise":["Nicht abrupt absetzen oder stark reduzieren: Gefahr eines lebensbedrohlichen Zustands mit Fieber, Muskelsteife und Bewusstseinsstörung.","Möglichst zu regelmässigen Zeiten einnehmen; eiweissreiche Mahlzeiten können die Wirkung abschwächen. Retardtabletten nicht zerkauen.","Bei Tagesschläfrigkeit oder plötzlichem Einschlafen nicht Auto fahren und keine Maschinen bedienen.","Angehörige sollten auf Spielsucht, Kaufsucht oder auffälliges Sexualverhalten achten und dies ärztlich melden."],"darreichung":["Tabletten","Retardtabletten","Gel zur Dauergabe in den Dünndarm (über Sonde und Pumpe)"]},"levodopa-carbidopa-entacapon":{"wirkmechanismus":"Ersetzt den bei Parkinson fehlenden Botenstoff Dopamin und sorgt dafür, dass jede Dosis länger wirkt. Levodopa wird im Gehirn zu Dopamin umgewandelt. Carbidopa hemmt den Abbau von Levodopa durch die Dopa-Decarboxylase ausserhalb des Gehirns. Entacapon hemmt zusätzlich im Körper das Enzym Catechol-O-Methyltransferase (COMT), verlängert so die Halbwertszeit von Levodopa und sorgt für gleichmässigere Spiegel im Blut und im Gehirn.","nebenwirkungen":{"sehrHaeufig":["Dyskinesien (unwillkürliche Überbewegungen)","Übelkeit","Rotbraune Verfärbung des Urins (harmlos)"],"haeufig":["Halluzinationen, Verwirrtheit, abnorme Träume","Schlaflosigkeit, Angst, Depression","Schwindel, Kopfschmerzen, Schläfrigkeit, Verschlechterung der Parkinson-Beschwerden","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Bluthochdruck","Durchfall, Verstopfung, Erbrechen, Bauchschmerzen, Mundtrockenheit","Anämie, Appetitverlust, Gewichtsabnahme","Brustschmerzen, Angina pectoris, unregelmässiger Herzschlag","Stürze, Muskelkrämpfe, vermehrtes Schwitzen"],"gelegentlich":["Herzinfarkt","Magen-Darm-Blutungen","Psychose, Unruhe","Thrombozytopenie (Mangel an Blutplättchen)","Erhöhte Leberwerte","Harnverhalt, Schluckbeschwerden"],"selten":["Krampfanfälle"],"unbekannt":["Suizidgedanken und Suizidversuch","Hepatitis","Colitis (Dickdarmentzündung) mit anhaltendem Durchfall","Impulskontrollstörungen (Spielsucht, Kaufsucht, Essattacken, gesteigertes sexuelles Verlangen)","Dopamin-Dysregulationssyndrom","Malignes neuroleptisches Syndrom (v. a. bei abruptem Absetzen)","Angioödem"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen; im Tierversuch schädliche Wirkungen von Levodopa/Carbidopa. Nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Levodopa geht in die Muttermilch über und kann die Milchbildung hemmen. Während der Behandlung nicht stillen.","hinweise":["Nicht abrupt absetzen (Gefahr eines lebensbedrohlichen Zustands mit Fieber und Muskelsteife); Umstellungen nur ärztlich.","Eisenpräparate mit 2–3 Stunden Abstand einnehmen.","Urin, Schweiss oder Speichel können sich rotbraun verfärben – harmlos, kann aber Wäsche verfärben.","Bei Tagesschläfrigkeit oder plötzlichem Einschlafen nicht Auto fahren; auf Spiel- oder Kaufsucht achten."],"darreichung":["Filmtabletten"]},"levofloxacin":{"wirkmechanismus":"Tötet Bakterien ab, indem es das Kopieren ihrer Erbsubstanz verhindert. Levofloxacin, die wirksame Hälfte (L-Isomer) von Ofloxacin, hemmt die bakteriellen Topoisomerasen II (DNA-Gyrase) und IV; es entstehen tödliche DNA-Brüche. Es wirkt gegen viele gramnegative Erreger und – besser als Ciprofloxacin – gegen Pneumokokken und atypische Erreger (Mykoplasmen, Chlamydien, Legionellen).","nebenwirkungen":{"haeufig":["Schlaflosigkeit","Kopfschmerzen, Schwindel","Übelkeit, Erbrechen, Durchfall","Erhöhte Leberwerte","Reaktionen an der Infusionsstelle (Schmerz, Rötung)"],"gelegentlich":["Pilzinfektionen","Leukopenie, Eosinophilie (Blutbildveränderungen)","Angst, Verwirrtheit, Nervosität, Schläfrigkeit, Zittern, Geschmacksstörungen","Drehschwindel, Atemnot","Bauchschmerzen, Verdauungsbeschwerden, Blähungen, Verstopfung","Hautausschlag, Juckreiz, Nesselsucht, vermehrtes Schwitzen","Gelenk- und Muskelschmerzen","Erhöhtes Kreatinin, Schwäche, Appetitlosigkeit"],"selten":["Sehnenentzündung (z. B. Achillessehne), Muskelschwäche","Thrombozytopenie, Neutropenie","Angioödem, Überempfindlichkeitsreaktionen, DRESS (schwere Arzneimittelreaktion mit Organbeteiligung)","Hypoglykämie (Unterzuckerung), vor allem bei Diabetes","Psychotische Reaktionen, Depression, Unruhe, Albträume","Krampfanfälle, Kribbeln, Sehstörungen, Tinnitus","Herzrasen, Herzklopfen, Blutdruckabfall","Akutes Nierenversagen, Fieber"],"unbekannt":["QT-Verlängerung, Kammertachykardie, Torsade de pointes","Sehnenriss, Rhabdomyolyse, Verschlechterung einer Myasthenia gravis","Periphere Neuropathie (teils bleibend), Geruchs- und Geschmacksverlust, Hörverlust","Agranulozytose, Panzytopenie, hämolytische Anämie, anaphylaktischer Schock","Schwere Leberschäden bis zum akuten Leberversagen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme), Lichtempfindlichkeit","Pseudomembranöse Kolitis, Pankreatitis, Hyperglykämie (Überzuckerung)","Aortenaneurysma und -dissektion, Herzklappenundichtigkeit"]},"schwangerschaft":"Kontraindiziert, da in Tierversuchen Gelenkknorpelschäden beim Jungtier auftraten.","stillzeit":"Kontraindiziert; Levofloxacin geht in die Muttermilch über und könnte den Gelenkknorpel des Säuglings schädigen.","hinweise":["Eisen-, Zink-, Magnesium- und Calciumpräparate sowie Antazida mindestens 2 Stunden Abstand einhalten.","Bei Sehnenschmerzen, Kribbeln, Taubheit, plötzlichen Brust-, Bauch- oder Rückenschmerzen sofort absetzen und ärztliche Hilfe holen.","Starke Sonne und Solarium meiden; Schwindel und Sehstörungen können das Autofahren beeinträchtigen."],"darreichung":["Filmtabletten","Infusionslösung"]},"levomepromazin":{"wirkmechanismus":"Dämpft Erregung, Unruhe und psychotische Symptome und wirkt stark beruhigend. Levomepromazin blockiert Dopamin-D2-Rezeptoren im Gehirn, ausgeprägt aber auch Histamin-H1-, Alpha-1-adrenerge, Muskarin- und Serotonin-5-HT2-Rezeptoren. Daraus erklären sich die starke Sedierung, der Blutdruckabfall und die anticholinergen Wirkungen. Zudem verstärkt es die Wirkung von Schmerzmitteln.","nebenwirkungen":{"unbekannt":["Starke Müdigkeit, Benommenheit, Schwindel","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Herzrasen","Mundtrockenheit, Verstopfung, Harnverhalt, Sehstörungen (anticholinerge Wirkungen)","Bewegungsstörungen (Zittern, Muskelsteifigkeit, Sitzunruhe), Spätdyskinesien","Gewichtszunahme; Prolaktinanstieg mit Milchfluss, Ausbleiben der Regel oder Potenzstörungen","QT-Verlängerung, Torsade de pointes (lebensgefährliche Herzrhythmusstörung), plötzlicher Herztod","Agranulozytose (Mangel an weissen Blutkörperchen), Leberschäden mit Gallenstau, Lichtempfindlichkeit der Haut","Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung), venöse Thromboembolien, Krampfanfälle"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen, Unruhe, Schläfrigkeit sowie Atem- und Trinkschwierigkeiten auftreten.","stillzeit":"Geht in die Muttermilch über; Stillen wird nicht empfohlen.","hinweise":["Wirkt stark beruhigend: keinen Alkohol trinken und nicht Auto fahren, besonders zu Beginn der Behandlung.","Langsam aufstehen – Gefahr von Schwindel und Stürzen durch Blutdruckabfall.","Haut vor starker Sonne schützen, sie kann lichtempfindlich werden.","Bei Fieber, Halsschmerzen oder Mundgeschwüren sofort ärztlich das Blutbild kontrollieren lassen."],"darreichung":["Tabletten","Tropfen","Injektionslösung"]},"levomethadon":{"wirkmechanismus":"Verhindert Entzugserscheinungen und Suchtdruck bei Opioidabhängigkeit, indem es lang anhaltend an den Opioidrezeptoren wirkt. Levomethadon ist das linksdrehende, pharmakologisch wirksame Enantiomer ((R)-Methadon) des Racemats Methadon und ein voller Agonist am µ-Opioidrezeptor; es ist etwa doppelt so stark wie Methadon. Zusätzlich wirkt es schwach hemmend am NMDA-Rezeptor. Die lange und individuell sehr unterschiedliche Halbwertszeit erlaubt eine einmal tägliche Einnahme, birgt aber besonders zu Beginn die Gefahr einer Anreicherung.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen"],"haeufig":["Verstopfung","Schläfrigkeit, Müdigkeit","Starkes Schwitzen","Schwindel, verschwommenes Sehen","Wassereinlagerungen, Gewichtszunahme","Euphorie, Halluzinationen","Hautausschlag"],"gelegentlich":["Mundtrockenheit","Harnverhalt","Blutdruckabfall, Hautrötung","Libidoverlust, Menstruationsstörungen"],"selten":["Langsamer Puls, Herzklopfen","QT-Verlängerung und Torsade de pointes (lebensgefährliche Herzrhythmusstörung)"],"unbekannt":["Atemdepression bis Atemstillstand, besonders bei Überdosierung","Hypoglykämie (Unterzuckerung)","Schlafbezogene Atmungsstörungen (zentrale Schlafapnoe)"]},"schwangerschaft":"Eine Substitution wird in der Schwangerschaft unter enger Betreuung fortgeführt, da ein Entzug Mutter und Kind gefährdet. Beim Neugeborenen kann ein Entzugssyndrom auftreten, das überwacht und behandelt werden muss.","stillzeit":"Geht in die Muttermilch über; Stillen nur nach ärztlicher Abwägung bei stabiler Dosis, Säugling auf Schläfrigkeit und Atemprobleme beobachten.","hinweise":["Levomethadon ist etwa doppelt so stark wie Methadon: Bei einer Umstellung die Dosis ärztlich anpassen und Verwechslungen vermeiden.","Für Kinder unerreichbar aufbewahren – schon geringe Mengen können tödlich sein.","Kein Alkohol und keine Beruhigungs- oder Schlafmittel ohne ärztliche Absprache.","Die Fahrtüchtigkeit ist besonders zu Beginn und bei Dosisänderungen stark eingeschränkt."],"darreichung":["Lösung zum Einnehmen"]},"levonorgestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft auf unterschiedliche Weise, je nach Anwendung. Als «Pille danach» verzögert oder verhindert eine einmalige hohe Dosis den Eisprung, sofern sie vor dem Anstieg des Hormons LH eingenommen wird; nach erfolgter Einnistung wirkt sie nicht und ist kein Abtreibungsmittel. In der Hormonspirale wird Levonorgestrel direkt in der Gebärmutter freigesetzt: Es verdickt den Schleim am Gebärmutterhals, hemmt die Beweglichkeit der Spermien und hält die Gebärmutterschleimhaut dünn, wodurch auch die Regelblutungen schwächer werden. Der Eisprung bleibt dabei meist erhalten.","nebenwirkungen":{"sehrHaeufig":["Notfallpille: Übelkeit, Unterbauchschmerzen, Kopfschmerzen, Müdigkeit","Zwischen- und Schmierblutungen; bei der Hormonspirale veränderte, oft schwächere oder ausbleibende Regelblutung","Hormonspirale: Bauch- und Beckenschmerzen, Entzündung von Scheide und Schamlippen (Vulvovaginitis), Ausfluss"],"haeufig":["Schwindel","Erbrechen, Durchfall","Brustspannen, Brustschmerzen","Verspätete Regelblutung (mehr als 7 Tage) nach der Notfallpille, schmerzhafte Regelblutung","Depressive Verstimmung, Depression, verminderte Libido","Akne, vermehrte Behaarung (Hirsutismus)","Eierstockzysten (meist harmlos und vorübergehend)","Ausstossung der Hormonspirale","Entzündung der inneren Geschlechtsorgane (Gebärmutter, Eileiter) bei liegender Hormonspirale"],"gelegentlich":["Haarausfall, Juckreiz, Ekzem","Wassereinlagerungen (Ödeme)"],"selten":["Durchstossung der Gebärmutterwand (Perforation), meist beim Einlegen der Spirale","Hautausschlag, Nesselsucht"],"sehrSelten":["Allergische Reaktionen mit Gesichtsschwellung (Notfallpille)"],"unbekannt":["Eileiterschwangerschaft, falls trotz Spirale eine Schwangerschaft eintritt"]},"schwangerschaft":"Bei bestehender Schwangerschaft nicht anwenden (die Notfallpille wirkt dann nicht). Eine versehentliche Einnahme schadet dem Kind nach bisherigen Erfahrungen nicht; tritt mit liegender Hormonspirale eine Schwangerschaft ein, sofort ärztlich abklären (Eileiterschwangerschaft ausschliessen).","stillzeit":"Erlaubt. Die Notfallpille möglichst direkt nach dem Stillen einnehmen und danach mindestens 8 Stunden nicht stillen; die Hormonspirale kann in der Stillzeit verwendet werden.","hinweise":["Die Notfallpille so früh wie möglich nach dem ungeschützten Verkehr einnehmen, spätestens nach 72 Stunden; in Apotheken nach Beratung ohne Rezept erhältlich.","Erbrechen innerhalb von 3 Stunden nach der Einnahme: erneut eine Tablette einnehmen.","Die Notfallpille schützt nicht für den Rest des Zyklus – bis zur nächsten Regel mit Kondom verhüten. Bleibt die Regel mehr als 5 Tage aus, einen Schwangerschaftstest machen.","Hormonspirale: Kontrolle einige Wochen nach dem Einlegen und danach regelmässig; bei starken Unterleibsschmerzen, Fieber oder ungewöhnlichem Ausfluss ärztlich abklären."],"darreichung":["Tabletten (Notfallverhütung)","Intrauterinpessar (Hormonspirale)"]},"levosimendan":{"wirkmechanismus":"Stärkt die Pumpkraft des Herzens, ohne seinen Sauerstoffbedarf wesentlich zu erhöhen, und erweitert die Blutgefässe. Levosimendan bindet calciumabhängig an Troponin C und macht die kontraktilen Eiweisse des Herzmuskels empfindlicher für Calcium (Calcium-Sensitizer). Zudem öffnet es ATP-abhängige Kaliumkanäle in der glatten Gefässmuskulatur und erweitert so Arterien, Venen und Herzkranzgefässe. Der aktive Metabolit OR-1896 hat eine lange Halbwertszeit, sodass die Wirkung nach einer 24-stündigen Infusion etwa 7–9 Tage anhält.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Hypotonie (Blutdruckabfall)","Ventrikuläre Tachykardie (Kammerherzrasen)"],"haeufig":["Hypokaliämie (Kaliummangel)","Schlaflosigkeit","Schwindel","Vorhofflimmern, Herzrasen, Extrasystolen","Verschlechterung der Herzinsuffizienz, Durchblutungsstörung des Herzmuskels (Myokardischämie)","Übelkeit, Erbrechen, Verstopfung, Durchfall","Verminderter Hämoglobinwert"],"unbekannt":["Kammerflimmern"]},"schwangerschaft":"Keine Erfahrungen beim Menschen, in Tierstudien fortpflanzungsschädigend; nur anwenden, wenn der Nutzen das Risiko für das Ungeborene überwiegt.","stillzeit":"Der aktive Metabolit kann in die Muttermilch übergehen; während und bis 14 Tage nach der Infusion nicht stillen.","hinweise":["Wird nur im Spital als Infusion unter Überwachung von EKG, Blutdruck, Herzfrequenz und Urinmenge gegeben.","Wegen des lange wirksamen Metaboliten werden Blutdruck, EKG und Kalium auch einige Tage nach Ende der Infusion kontrolliert."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"levothyroxin":{"wirkmechanismus":"Ersetzt das fehlende körpereigene Schilddrüsenhormon und normalisiert so Stoffwechsel, Energiehaushalt und Herzfrequenz. Levothyroxin ist chemisch identisch mit dem natürlichen Thyroxin (T4) und wird in Leber, Niere und anderen Geweben zum eigentlich wirksamen Trijodthyronin (T3) umgewandelt, das an Schilddrüsenhormon-Rezeptoren im Zellkern bindet und die Ablesung zahlreicher Gene steuert. Zugleich hemmt es über eine Rückkopplung die TSH-Ausschüttung der Hirnanhangdrüse, was beim Kropf das Wachstum der Schilddrüse bremst. Wegen der langen Halbwertszeit von etwa einer Woche stellt sich die volle Wirkung erst nach einigen Wochen ein.","nebenwirkungen":{"sehrHaeufig":["Herzklopfen (bei zu hoher Dosis)","Schlaflosigkeit (bei zu hoher Dosis)","Kopfschmerzen (bei zu hoher Dosis)"],"haeufig":["Nervosität (bei zu hoher Dosis)","Beschleunigter Puls (bei zu hoher Dosis)"],"unbekannt":["Herzrhythmusstörungen (z. B. Vorhofflimmern), Angina pectoris","Zittern, innere Unruhe","Übermässiges Schwitzen, Wärmeunverträglichkeit, Fieber, Hitzewallungen","Durchfall, Erbrechen, Gewichtsverlust","Muskelschwäche, Muskelkrämpfe; Osteoporose bei langfristig zu hoher Dosis","Menstruationsstörungen","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz, Angioödem)","Erhöhter Hirndruck (Pseudotumor cerebri), v. a. bei Kindern"]},"schwangerschaft":"Erlaubt und wichtig: Eine Schilddrüsenunterfunktion muss in der Schwangerschaft konsequent behandelt werden; der Bedarf steigt meist, TSH und Dosis ärztlich kontrollieren. Die Kombination mit einem Thyreostatikum ist in der Schwangerschaft kontraindiziert.","stillzeit":"Erlaubt; in die Muttermilch gehen nur sehr geringe Mengen über.","hinweise":["Morgens nüchtern mindestens 30 Minuten vor dem Frühstück mit Wasser einnehmen, nicht mit Kaffee oder Milch.","Mindestens 2–4 Stunden Abstand zu Calcium, Eisen, Magnesium, Antazida und Gallensäurebindern halten.","Präparatewechsel nur mit TSH-Kontrolle: Präparate verschiedener Hersteller sind nicht immer gleichwertig.","Herzklopfen, Schlaflosigkeit, Zittern oder Schwitzen können auf eine zu hohe Dosis hinweisen – ärztlich kontrollieren lassen."],"darreichung":["Tabletten","Weichkapseln","Lösung zum Einnehmen"]},"levothyroxin-liothyronin":{"wirkmechanismus":"Ersetzt fehlende Schilddrüsenhormone und normalisiert so Stoffwechsel, Energiehaushalt und Herz-Kreislauf-Funktion. Die Kombination enthält Levothyroxin (T4), das im Körper laufend in die aktive Form umgewandelt wird, und Liothyronin (T3), die direkt wirksame Form, im Verhältnis von etwa 5 zu 1. T3 bindet an Rezeptoren im Zellkern und steuert die Ablesung zahlreicher Gene. Der T3-Anteil wirkt rascher und kürzer als T4.","nebenwirkungen":{"unbekannt":["Bei zu hoher Dosis Zeichen einer Überfunktion: Herzklopfen, Herzrasen, Herzrhythmusstörungen","Brustschmerzen (Angina pectoris)","Zittern, innere Unruhe, Schlafstörungen","Vermehrtes Schwitzen, Wärmeunverträglichkeit, Fieber","Gewichtsverlust, Durchfall","Kopfschmerzen, Muskelkrämpfe oder Muskelschwäche","Menstruationsstörungen","Allergische Hautreaktionen"]},"schwangerschaft":"Eine Unterfunktion muss in der Schwangerschaft weiterbehandelt werden; bevorzugt wird Levothyroxin allein. Die Kombination mit Thyreostatika ist kontraindiziert.","stillzeit":"Erlaubt; es gehen nur geringe Mengen in die Muttermilch über.","hinweise":["Morgens nüchtern mit Wasser einnehmen, mindestens eine halbe Stunde vor dem Frühstück.","Calcium-, Eisen- oder Magnesiumpräparate und Säurebinder mit mindestens 2 Stunden Abstand einnehmen.","Schilddrüsenwerte regelmässig kontrollieren lassen; Herzklopfen, Zittern oder Schlaflosigkeit melden (mögliche Überdosierung).","Nicht zur Gewichtsabnahme verwenden."],"darreichung":["Tabletten"]},"lidocain":{"wirkmechanismus":"Betäubt die Nerven an der Stelle, an der es angewendet wird, sodass Schmerzreize nicht mehr weitergeleitet werden. Lidocain blockiert spannungsabhängige Natriumkanäle der Nervenmembran von innen und verhindert so die Entstehung und Weiterleitung von Aktionspotenzialen; die Wirkung tritt rasch ein und hält etwa 1–2 Stunden an. Am Herzen wirkt es als Klasse-IB-Antiarrhythmikum: Es bindet bevorzugt an Natriumkanäle von geschädigten, häufig erregten Kammerzellen und unterdrückt dort Rhythmusstörungen. Lidocain wird in der Leber vor allem über CYP1A2 und CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Blutdruckabfall (Hypotonie) und Übelkeit (bei Regionalanästhesie)","Reaktionen an der Klebestelle (Rötung, Juckreiz, Brennen) beim Pflaster"],"haeufig":["Kribbeln (Parästhesien), Schwindel","Bradykardie (verlangsamter Herzschlag)","Blutdruckanstieg","Erbrechen"],"gelegentlich":["Zeichen einer Überdosierung am Nervensystem: Taubheit von Lippen und Zunge, Ohrensausen, Sehstörungen, Zittern, Benommenheit, Krampfanfälle"],"selten":["Allergische Reaktionen bis zum anaphylaktischen Schock","Herzrhythmusstörungen und Herzstillstand","Atemdepression (Atemdämpfung)","Nervenschädigung, Arachnoiditis (Entzündung der Rückenmarkshaut) nach rückenmarknaher Anästhesie","Doppelbilder"],"unbekannt":["Methämoglobinämie (verminderter Sauerstofftransport im Blut), v. a. bei Säuglingen und grossflächiger Anwendung","Örtliche Reizung, Brennen oder Schwellung an der Anwendungsstelle"]},"schwangerschaft":"Wird seit langem in der Schwangerschaft verwendet und gilt in üblicher Dosierung als vertretbar. Bei Leitungsanästhesie in Gebärmutterhalsnähe (Parazervikalblock) kann beim Kind der Herzschlag langsamer werden.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; Stillen ist erlaubt.","hinweise":["Nach Betäubung im Mund oder Rachen etwa 1 Stunde nichts essen oder heiss trinken (Gefahr von Bissverletzungen und Verschlucken).","Nach einer örtlichen Betäubung kann die Fahrtüchtigkeit vorübergehend eingeschränkt sein.","Gel, Spray und Salbe nicht grossflächig auf verletzte Haut auftragen und bei Kindern genau nach Packungsbeilage dosieren.","Lidocain-Pflaster nur auf intakte, unverletzte Haut kleben und höchstens 12 Stunden innerhalb von 24 Stunden tragen."],"darreichung":["Injektionslösung","Gel","Spray","Salbe","Wirkstoffhaltiges Pflaster","Lutschtabletten"]},"lidocain-prilocain":{"wirkmechanismus":"Macht die Haut an der behandelten Stelle für einige Stunden unempfindlich gegen Schmerz. Lidocain und Prilocain bilden zusammen ein bei Raumtemperatur flüssiges («eutektisches») Gemisch, das gut in die Haut eindringt. Dort blockieren beide Wirkstoffe die Natriumkanäle der Nervenendigungen und unterbrechen so die Schmerzweiterleitung. Auf intakter Haut braucht es dafür meist rund 60 Minuten Einwirkzeit unter einem Abdeckverband.","nebenwirkungen":{"sehrHaeufig":["Blässe, Rötung und Schwellung bei Anwendung auf Unterschenkelgeschwüren"],"haeufig":["Vorübergehende Blässe, Rötung oder Schwellung der Haut an der Anwendungsstelle","Brennen, Juckreiz oder Reizung (Genitalschleimhaut, Beingeschwüre)"],"gelegentlich":["Anfängliches Brennen, Juckreiz oder Wärmegefühl auf intakter Haut"],"selten":["Methämoglobinämie (Sauerstoffmangel im Blut), v. a. bei Säuglingen","Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Punktförmige Hautblutungen (v. a. bei Kindern mit Neurodermitis oder Dellwarzen)","Hornhautreizung bei versehentlichem Kontakt mit dem Auge"]},"schwangerschaft":"Beide Wirkstoffe passieren die Plazenta; Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko. Anwendung in üblicher Menge nach Abwägung möglich.","stillzeit":"Lidocain und Prilocain gehen nur in sehr geringen Mengen in die Muttermilch über; Stillen ist bei üblicher Anwendung möglich.","hinweise":["Crème dick auftragen und mit einem Folienverband abdecken; auf intakter Haut meist 1 Stunde, auf Genitalschleimhaut nur 5–10 Minuten einwirken lassen.","Nicht in Augen oder Gehörgang bringen; die betäubte Stelle vor Verletzungen (Kratzen, Hitze, Kälte) schützen.","Bei Säuglingen und Kleinkindern die für das Alter angegebene Höchstmenge und Einwirkzeit genau einhalten."],"darreichung":["Crème","Pflaster"]},"linaclotid":{"wirkmechanismus":"Erhöht die Flüssigkeitsmenge im Darm, macht den Stuhl weicher und lindert Bauchschmerzen. Linaclotid ist ein kleines Peptid, das auf der Oberfläche der Darmschleimhaut den Rezeptor Guanylatcyclase C aktiviert. Der Anstieg des Botenstoffs cGMP führt zur Abgabe von Chlorid und Bicarbonat in den Darm, Wasser folgt nach, und die Darmpassage beschleunigt sich. Ausserhalb der Zellen dämpft cGMP zudem schmerzleitende Nervenfasern. Linaclotid wird kaum ins Blut aufgenommen.","nebenwirkungen":{"sehrHaeufig":["Durchfall"],"haeufig":["Bauchschmerzen","Blähungen","Aufgeblähter Bauch","Schwindel","Magen-Darm-Infekt (virale Gastroenteritis)"],"gelegentlich":["Dehydratation (Flüssigkeitsmangel)","Hypokaliämie (Kaliummangel)","Verminderter Appetit","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Stuhlinkontinenz","Starker Stuhldrang","Blutungen aus dem Enddarm oder aus Hämorrhoiden"],"unbekannt":["Hautausschlag"]},"schwangerschaft":"Begrenzte Erfahrungen; aus Vorsicht während der Schwangerschaft nicht anwenden.","stillzeit":"Linaclotid wird kaum ins Blut aufgenommen, ein Übergang in die Muttermilch ist unwahrscheinlich; Anwendung nach ärztlicher Abwägung.","hinweise":["Einmal täglich mindestens 30 Minuten vor einer Mahlzeit einnehmen.","Bessern sich die Beschwerden nach 4 Wochen nicht, die Behandlung ärztlich überprüfen lassen.","Starken oder anhaltenden Durchfall ärztlich melden."],"darreichung":["Hartkapseln"]},"linagliptin":{"wirkmechanismus":"Verstärkt die Wirkung körpereigener Darmhormone, die nach dem Essen die Insulinausschüttung anregen. Linagliptin hemmt das Enzym Dipeptidylpeptidase-4 (DPP-4) fest und lang anhaltend, sodass die Inkretine GLP-1 und GIP länger aktiv bleiben; die Insulinfreisetzung steigt blutzuckerabhängig und die Glukagonausschüttung sinkt. Linagliptin wird überwiegend unverändert über Galle und Darm ausgeschieden, nur etwa 5 % über die Nieren – deshalb ist bei eingeschränkter Nieren- oder Leberfunktion keine Dosisanpassung nötig.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) in Kombination mit Metformin und Sulfonylharnstoff"],"haeufig":["Erhöhte Lipase-Werte im Blut"],"gelegentlich":["Nasopharyngitis (Nasen-Rachen-Entzündung)","Überempfindlichkeitsreaktionen (z. B. Überempfindlichkeit der Bronchien)","Husten","Hautausschlag","Erhöhte Amylase-Werte im Blut","Verstopfung (in Kombination mit Insulin)"],"selten":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)","Urtikaria (Nesselsucht)","Bullöses Pemphigoid (blasenbildende Hauterkrankung)"]},"schwangerschaft":"Vorsichtshalber nicht anwenden: Es liegen keine ausreichenden Erfahrungen vor; in der Schwangerschaft wird Insulin bevorzugt.","stillzeit":"Nicht empfohlen: Linagliptin geht bei Tieren in die Milch über, ein Risiko für das gestillte Kind ist nicht auszuschliessen – ärztlich entscheiden, ob abgestillt oder die Behandlung beendet wird.","hinweise":["Einmal täglich zu einer beliebigen Tageszeit, unabhängig von den Mahlzeiten einnehmen.","Bei anhaltenden, starken Bauchschmerzen sofort ärztlich abklären lassen (mögliche Bauchspeicheldrüsenentzündung).","In Kombination mit Sulfonylharnstoff oder Insulin kann eine Unterzuckerung die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"linezolid":{"wirkmechanismus":"Verhindert, dass Bakterien Eiweisse herstellen können, und stoppt so ihr Wachstum. Linezolid bindet an die 23S-ribosomale RNA der 50S-Untereinheit und verhindert die Bildung des 70S-Initiationskomplexes – ein Mechanismus, den kein anderes gebräuchliches Antibiotikum nutzt, daher wirkt es auch gegen Methicillin-resistente Staphylokokken (MRSA) und Vancomycin-resistente Enterokokken. Gegen gramnegative Bakterien ist es unwirksam. Zusätzlich hemmt Linezolid schwach und reversibel die Monoaminoxidase (MAO), was Wechselwirkungen mit serotonergen und blutdrucksteigernden Mitteln erklärt.","nebenwirkungen":{"haeufig":["Candida-Infektionen (Mund- oder Scheidenpilz)","Kopfschmerzen, Schwindel, Schlaflosigkeit","Metallischer Geschmack (Geschmacksstörung)","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung","Anämie (Blutarmut)","Bluthochdruck","Erhöhte Leber- und Nierenwerte","Juckreiz, Hautausschlag, Fieber"],"gelegentlich":["Thrombozytopenie, Leukopenie, Neutropenie (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Krampfanfälle","Kribbeln und Taubheitsgefühl","Verschwommenes Sehen","Tinnitus (Ohrgeräusche)","Herzrhythmusstörungen (Tachykardie), vorübergehende Durchblutungsstörung des Gehirns (TIA)","Hyponatriämie (Natriummangel)","Pankreatitis, Nierenversagen"],"selten":["Panzytopenie (Mangel an allen Blutzellen)","Gesichtsfeldausfälle","Pseudomembranöse Kolitis (Clostridioides difficile)","Oberflächliche Zahnverfärbung (entfernbar)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"],"unbekannt":["Myelosuppression, sideroblastische Anämie","Serotoninsyndrom","Laktatazidose","Periphere Neuropathie und optische Neuropathie bis zum Sehverlust","Hypoglykämie (Unterzuckerung)","Anaphylaxie, Angioödem","Haarausfall"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit anwenden; es gibt kaum Erfahrungen und Tierversuche zeigten schädliche Wirkungen.","stillzeit":"Vor und während der Behandlung abstillen; Linezolid geht im Tierversuch in die Milch über.","hinweise":["Grössere Mengen tyraminreicher Lebensmittel meiden (gereifter Käse, Hefeextrakt, Sojasauce, Salami, Fassbier, Rotwein) – Gefahr eines Blutdruckanstiegs.","Blutbild wöchentlich kontrollieren; die Behandlung dauert in der Regel höchstens 28 Tage.","Sehstörungen (verschwommenes Sehen, Farbsehen, Gesichtsfeldausfälle) und Kribbeln in Händen oder Füssen sofort melden.","Alle anderen Medikamente angeben, besonders Antidepressiva, Migränemittel, Schmerzmittel und Erkältungsmittel mit Pseudoephedrin."],"darreichung":["Filmtabletten","Infusionslösung"]},"liothyronin":{"wirkmechanismus":"Ersetzt fehlendes Schilddrüsenhormon und normalisiert so Stoffwechsel, Energiehaushalt und Herz-Kreislauf-Funktion. Liothyronin ist synthetisches Trijodthyronin (T3), die biologisch aktive Form des Schilddrüsenhormons. Es bindet an Schilddrüsenhormon-Rezeptoren im Zellkern und steuert die Ablesung zahlreicher Gene. Im Vergleich zu Levothyroxin (T4) wirkt es rascher und kürzer.","nebenwirkungen":{"unbekannt":["Bei zu hoher Dosis Zeichen einer Überfunktion: Herzklopfen, Herzrasen, Herzrhythmusstörungen","Brustschmerzen (Angina pectoris)","Zittern, innere Unruhe, Schlafstörungen","Vermehrtes Schwitzen, Wärmeunverträglichkeit, Fieber","Gewichtsverlust, Durchfall","Kopfschmerzen, Muskelkrämpfe oder Muskelschwäche","Menstruationsstörungen","Allergische Hautreaktionen"]},"schwangerschaft":"Eine Unterfunktion muss in der Schwangerschaft weiterbehandelt werden; die Dosis wird oft angepasst. Bevorzugt wird Levothyroxin allein. Die Kombination mit Thyreostatika ist kontraindiziert.","stillzeit":"Erlaubt; es gehen nur geringe Mengen in die Muttermilch über.","hinweise":["Morgens nüchtern mit Wasser einnehmen, mindestens eine halbe Stunde vor dem Frühstück.","Calcium-, Eisen- oder Magnesiumpräparate und Säurebinder mit mindestens 2 Stunden Abstand einnehmen.","Schilddrüsenwerte regelmässig kontrollieren lassen; Herzklopfen, Zittern oder Schlaflosigkeit melden (mögliche Überdosierung).","Nicht zur Gewichtsabnahme verwenden."],"darreichung":["Tabletten"]},"lipegfilgrastim":{"wirkmechanismus":"Regt das Knochenmark an, mehr neutrophile Granulozyten (weisse Blutkörperchen zur Infektabwehr) zu bilden. Lipegfilgrastim ist Filgrastim (gentechnisch hergestellter humaner G-CSF), an das über eine Zuckerkette Polyethylenglykol gekoppelt ist (Glykopegylierung). Es bindet an den G-CSF-Rezeptor und fördert Vermehrung, Ausreifung und Freisetzung der Neutrophilen. Die Kopplung verlangsamt die Ausscheidung, sodass eine Injektion pro Chemotherapie-Zyklus genügt.","nebenwirkungen":{"sehrHaeufig":["Muskel- und Knochenschmerzen (z. B. Knochen-, Gelenk-, Rückenschmerzen)","Übelkeit"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Kaliummangel (Hypokaliämie)","Kopfschmerzen","Hautreaktionen (Rötung, Ausschlag)","Brustschmerzen"],"gelegentlich":["Leukozytose (Anstieg der weissen Blutkörperchen)","Überempfindlichkeitsreaktionen","Lungenkomplikationen (Lungeninfiltrate, Lungenödem, interstitielle Pneumonie)","Reaktionen an der Einstichstelle","Erhöhte alkalische Phosphatase und LDH"],"unbekannt":["Milzvergrösserung, Milzriss","Kapillarlecksyndrom","Glomerulonephritis (Nierenentzündung)","Aortitis (Entzündung der Hauptschlagader)","Sichelzellkrisen bei Sichelzellkrankheit","Sweet-Syndrom (akute fieberhafte neutrophile Dermatose)"]},"schwangerschaft":"Vorsichtshalber nicht anwenden (keine ausreichenden Daten).","stillzeit":"Nur nach ärztlicher Abwägung; entweder Stillen oder Behandlung unterbrechen.","hinweise":["Einmal pro Chemotherapie-Zyklus, etwa 24 Stunden nach der Chemotherapie unter die Haut spritzen.","Schmerzen im linken Oberbauch oder in der Schulterspitze, Atemnot oder Husten mit Fieber sofort melden.","Knochenschmerzen sind häufig; einfache Schmerzmittel helfen meist.","Fertigspritze im Kühlschrank lagern, nicht einfrieren."],"darreichung":["Injektionslösung in Fertigspritze"]},"lipidemulsion":{"wirkmechanismus":"Liefert dem Körper Energie und lebenswichtige Fettsäuren, wenn er nicht über den Darm ernährt werden kann. Die Emulsion besteht aus feinen Fetttröpfchen aus Soja-, Oliven-, Fisch- oder Kokosöl (mittelkettige Triglyceride), die mit Eilecithin stabilisiert sind und sich im Blut ähnlich wie natürliche Chylomikronen verhalten. Die Lipoproteinlipase spaltet die Triglyceride in freie Fettsäuren, die zur Energiegewinnung und zum Aufbau von Zellmembranen dienen; essenzielle Fettsäuren beugen einem Mangel vor.","nebenwirkungen":{"haeufig":["Leichter Anstieg der Körpertemperatur"],"gelegentlich":["Schüttelfrost","Appetitlosigkeit","Übelkeit, Erbrechen"],"selten":["Überempfindlichkeitsreaktionen (z. B. Hautausschlag, Nesselsucht, anaphylaktische Reaktion)","Blutdruckabfall oder -anstieg","Atemnot (Dyspnoe), Herzrasen","Kopfschmerzen, Hitze- oder Kältegefühl","Schmerzen in Nacken, Rücken, Knochen, Brust oder Lendenbereich"],"sehrSelten":["Priapismus (schmerzhafte Dauererektion)"],"unbekannt":["Fettüberladungssyndrom (Fieber, Fettleber, Leber- und Milzvergrösserung, Blutgerinnungsstörung, Koma)","Erhöhte Leberwerte und Gallenstau bei langdauernder parenteraler Ernährung"]},"schwangerschaft":"Bei klarer Notwendigkeit als Teil einer parenteralen Ernährung möglich; Daten sind begrenzt.","stillzeit":"Bei klarer Notwendigkeit möglich; Daten sind begrenzt.","hinweise":["Triglyceride, Blutzucker, Leberwerte und Blutbild werden regelmässig kontrolliert.","Die vorgegebene Infusionsgeschwindigkeit nicht überschreiten (Gefahr eines Fettüberladungssyndroms).","Kann Laborwerte (z. B. Bilirubin, Hämoglobin, Sauerstoffsättigung) verfälschen – Blut möglichst erst einige Stunden nach Infusionsende abnehmen.","Bei Neugeborenen und Kleinkindern Beutel und Infusionsleitung vor Licht schützen."],"darreichung":["Emulsion zur Infusion"]},"liraglutid":{"wirkmechanismus":"Wirkt wie das körpereigene Darmhormon GLP-1, das nach dem Essen ausgeschüttet wird. Liraglutid aktiviert den GLP-1-Rezeptor: Die Insulinfreisetzung steigt blutzuckerabhängig, die Glukagonausschüttung sinkt und der Magen entleert sich langsamer. Im Gehirn verstärkt es das Sättigungsgefühl und senkt den Appetit, was zur Gewichtsabnahme führt. Über eine Fettsäure-Seitenkette bindet es an Albumin und wirkt etwa 24 Stunden, deshalb wird es einmal täglich gespritzt.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Durchfall","Erbrechen und Verstopfung (unter Saxenda sehr häufig, unter Victoza häufig)"],"haeufig":["Hypoglykämie (Unterzuckerung), vor allem in Kombination mit Sulfonylharnstoff oder Insulin","Appetitminderung","Kopfschmerzen, Schwindel","Verdauungsbeschwerden, Bauchschmerzen, Gastritis, Reflux, Aufstossen, Blähungen","Gallensteine (Cholelithiasis; vor allem unter Saxenda)","Erhöhter Puls","Müdigkeit, Schlaflosigkeit (Saxenda)","Reaktionen an der Injektionsstelle"],"gelegentlich":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung; unter Victoza sehr selten)","Cholezystitis (Gallenblasenentzündung)","Dehydratation (Flüssigkeitsmangel)","Eingeschränkte Nierenfunktion bis akutes Nierenversagen","Nesselsucht, Juckreiz, Hautausschlag","Verzögerte Magenentleerung","Unwohlsein"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Darmverschluss (Ileus)"]},"schwangerschaft":"Nicht anwenden: Die Erfahrungen sind begrenzt, Tierversuche zeigten Fruchtschädigung. Bei Kinderwunsch oder Schwangerschaft absetzen; bei Diabetes wird auf Insulin umgestellt.","stillzeit":"Nicht anwenden, da keine ausreichenden Erfahrungen vorliegen.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten unter die Haut spritzen (Bauch, Oberschenkel oder Oberarm); die Dosis wird zur besseren Verträglichkeit schrittweise gesteigert.","Bei anhaltenden, starken Bauchschmerzen sofort ärztlich abklären lassen (mögliche Bauchspeicheldrüsenentzündung); bei Übelkeit, Erbrechen oder Durchfall ausreichend trinken.","Vor Operationen, Narkosen oder Magenspiegelungen die Behandlung angeben.","Saxenda: Bei weniger als 5 % Gewichtsabnahme nach 12 Wochen mit der Erhaltungsdosis wird die Behandlung beendet."],"darreichung":["Injektionslösung im Fertigpen"]},"lisdexamfetamin":{"wirkmechanismus":"Wirkt wie Dexamfetamin, wird aber erst im Körper aktiviert: Lisdexamfetamin selbst ist unwirksam und wird nach der Aufnahme vor allem in den roten Blutkörperchen langsam in Dexamfetamin und die Aminosäure L-Lysin gespalten. Dexamfetamin hemmt die Wiederaufnahme von Dopamin und Noradrenalin und setzt diese Botenstoffe zusätzlich aus den Nervenendigungen frei. Durch die gleichmässige Umwandlung hält die Wirkung über den Tag an.","nebenwirkungen":{"sehrHaeufig":["Appetitminderung","Gewichtsabnahme","Schlaflosigkeit","Kopfschmerzen","Mundtrockenheit (Erwachsene), Oberbauchschmerzen (Kinder)"],"haeufig":["Reizbarkeit, Unruhe, Angst, Stimmungsschwankungen, Tics","Schwindel, Zittern, Schläfrigkeit","Herzrasen, Herzklopfen, Blutdruckanstieg","Übelkeit, Erbrechen, Durchfall, Verstopfung","Vermehrtes Schwitzen, Atemnot","Erektionsstörungen, verminderte Libido","Müdigkeit, Fieber, Zähneknirschen"],"gelegentlich":["Aggressivität, Manie, Halluzinationen, Depression, Euphorie","Ohnmacht (Synkope), Dyskinesien, Geschmacksstörungen","Verschwommenes Sehen, Pupillenerweiterung","Raynaud-Phänomen (kalte, weisse Finger)","Nasenbluten","Nesselsucht, Hautausschlag","Brustschmerzen"],"unbekannt":["Psychotische Episoden","Krampfanfälle","Kardiomyopathie","Anaphylaxie, Angioödem, Stevens-Johnson-Syndrom","Eosinophile Hepatitis","Abhängigkeit, Missbrauch"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Amphetamine können beim Neugeborenen zu Entzugssymptomen, Frühgeburt und niedrigem Geburtsgewicht führen.","stillzeit":"Amphetamine gehen in die Muttermilch über; nicht stillen.","hinweise":["Morgens einnehmen; die Kapsel kann geöffnet und der Inhalt in Wasser, Joghurt oder Orangensaft vollständig aufgelöst werden.","Untersteht dem Betäubungsmittelgesetz: sicher aufbewahren, nicht weitergeben.","Puls, Blutdruck, Gewicht und bei Kindern die Körpergrösse regelmässig kontrollieren; die Notwendigkeit der Behandlung periodisch überprüfen.","Alkohol meiden; die Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Kapseln"]},"lisinopril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II blockiert. Lisinopril hemmt direkt – ohne vorherige Aktivierung in der Leber – das Angiotensin-Konversionsenzym (ACE). Angiotensin II und Aldosteron sinken, die Gefässe weiten sich und die Niere scheidet mehr Salz und Wasser aus; das entlastet Herz und Nieren. Lisinopril wird nicht verstoffwechselt, sondern unverändert über die Niere ausgeschieden; der Anstieg von Bradykinin erklärt Reizhusten und Angioödeme.","nebenwirkungen":{"haeufig":["Schwindel","Kopfschmerzen","Hypotonie (tiefer Blutdruck), auch beim Aufstehen","Trockener Reizhusten","Durchfall, Erbrechen","Nierenfunktionsstörung"],"gelegentlich":["Stimmungsschwankungen, Schlafstörungen, Halluzinationen","Kribbeln, Drehschwindel, Geschmacksstörungen","Herzinfarkt oder Schlaganfall (infolge starken Blutdruckabfalls bei Risikopatienten), Herzklopfen, beschleunigter Puls, Raynaud-Syndrom","Schnupfen, Übelkeit, Bauchschmerzen, Verdauungsstörungen","Hautausschlag, Juckreiz","Erektionsstörungen, Müdigkeit, Schwäche","Hyperkaliämie (erhöhtes Kalium), Anstieg von Harnstoff, Kreatinin und Leberwerten"],"selten":["Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen), Überempfindlichkeit","Hyponatriämie (Natriummangel), SIADH","Verwirrtheit, Geruchsstörungen, Mundtrockenheit","Nesselsucht, Haarausfall, Psoriasis","Akutes Nierenversagen, Urämie","Brustvergrösserung beim Mann","Abfall von Hämoglobin und Hämatokrit"],"sehrSelten":["Knochenmarkdepression, Agranulozytose, Thrombozytopenie, hämolytische Anämie","Hypoglykämie (Unterzuckerung)","Bronchospasmus, Sinusitis, allergische Alveolitis bzw. eosinophile Pneumonie","Pankreatitis, intestinales Angioödem (Schwellung der Darmwand)","Hepatitis, Gelbsucht, Leberversagen","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme, Pemphigus","Vermehrtes Schwitzen, stark verminderte Harnmenge"],"unbekannt":["Depressive Verstimmung","Synkope (Ohnmacht)"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten zum Übergang in die Muttermilch fehlen; besser untersuchte Alternativen wählen, besonders bei Neugeborenen und Frühgeborenen.","hinweise":["Bei Schwellung von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notruf wählen (Angioödem, auch nach langer Einnahme möglich).","Ein anhaltender trockener Reizhusten ist eine typische Nebenwirkung – ärztlich besprechen, nicht eigenmächtig absetzen.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel und Kaliumpräparate nur nach ärztlicher Rücksprache.","Bei starkem Durchfall, Erbrechen oder Flüssigkeitsmangel ärztlich klären, ob die Einnahme vorübergehend pausiert werden soll."],"darreichung":["Tabletten"]},"lithium":{"wirkmechanismus":"Gleicht starke Stimmungsschwankungen aus und senkt das Risiko für Rückfälle. Der genaue Mechanismus ist nicht vollständig geklärt: Lithium beeinflusst Botenstoffsysteme (Serotonin, Noradrenalin, Glutamat) und hemmt Enzyme der Signalübertragung in den Nervenzellen wie die Inositol-Monophosphatase und die Glykogensynthase-Kinase-3. Lithium hat eine enge therapeutische Breite und wird fast vollständig über die Niere ausgeschieden; die Ausscheidung hängt eng vom Natrium- und Wasserhaushalt ab.","nebenwirkungen":{"sehrHaeufig":["Feinschlägiges Zittern der Hände","Vermehrtes Wasserlassen (Polyurie) und starker Durst"],"haeufig":["Übelkeit, Durchfall, Bauchbeschwerden (v. a. zu Beginn)","Gewichtszunahme","Hypothyreose (Schilddrüsenunterfunktion), Struma (Kropf)","Ödeme (Wassereinlagerungen)","Leukozytose (Vermehrung der weissen Blutkörperchen)","Metallischer Geschmack, Muskelschwäche"],"unbekannt":["Lithiumvergiftung bei zu hohem Spiegel: grobes Zittern, Erbrechen, Durchfall, Schwindel, Verwirrtheit, Krampfanfälle bis Koma","Nephrogener Diabetes insipidus (Niere kann den Urin nicht mehr konzentrieren)","Chronische Nierenschädigung und Nierentumoren (Mikrozysten, Onkozytome) bei Langzeitbehandlung","Hyperparathyreoidismus mit erhöhtem Calcium","Herzrhythmusstörungen, QT-Verlängerung, Demaskierung eines Brugada-Syndroms","Akne, Verschlechterung einer Psoriasis, Haarausfall","Gedächtnis- und Konzentrationsstörungen","Erhöhter Hirndruck (benigne intrakranielle Hypertension)"]},"schwangerschaft":"Im ersten Drittel erhöhtes Risiko für Herzfehlbildungen (u. a. Ebstein-Anomalie); nur nach strenger ärztlicher Abwägung und mit engmaschigen Spiegelkontrollen. Beim Neugeborenen können Vergiftungszeichen (z. B. Muskelschlaffheit, Trinkschwäche) und Schilddrüsenstörungen auftreten.","stillzeit":"Lithium geht in die Muttermilch über und kann beim Säugling zu Vergiftungen führen. Stillen ist kontraindiziert.","hinweise":["Blutspiegel regelmässig kontrollieren (Blutentnahme 12 Stunden nach der letzten Einnahme), zusätzlich Nieren- und Schilddrüsenwerte sowie Calcium.","Ausreichend trinken und Salz nicht stark einschränken; bei Fieber, Durchfall, Erbrechen, starkem Schwitzen oder Hitze ärztlich Rücksprache halten.","Vergiftungszeichen (grobes Zittern, Erbrechen, Durchfall, Schwindel, undeutliche Sprache, Verwirrtheit) sofort ärztlich abklären.","Keine Schmerzmittel wie Ibuprofen oder Diclofenac und keine neuen Blutdruck- oder Entwässerungsmittel ohne Rücksprache; das Präparat nicht ohne ärztliche Anordnung wechseln."],"darreichung":["Retardtabletten","Filmtabletten"]},"loperamid":{"wirkmechanismus":"Bremst die Darmbewegungen, sodass dem Stuhl mehr Wasser entzogen wird und der Durchfall nachlässt. Loperamid bindet an µ-Opioidrezeptoren in der Darmwand und hemmt dort die Freisetzung von Acetylcholin und Prostaglandinen: Die Peristaltik nimmt ab, die Passagezeit verlängert sich, Wasser und Salze werden vermehrt zurückgeholt, und der Schliessmuskel am After spannt sich stärker an. In üblicher Dosis gelangt es kaum ins Gehirn, weil es in der Leber stark abgebaut wird (CYP3A4, CYP2C8) und die Transportpumpe P-Glykoprotein es aus dem Gehirn hinausbefördert.","nebenwirkungen":{"haeufig":["Verstopfung (Obstipation)","Übelkeit","Blähungen","Kopfschmerzen","Schwindel"],"gelegentlich":["Bauchschmerzen und Bauchbeschwerden","Mundtrockenheit","Erbrechen","Dyspepsie (Verdauungsbeschwerden)","Schläfrigkeit","Hautausschlag"],"selten":["Darmverschluss (Ileus) und Megakolon (stark erweiterter Dickdarm)","Harnverhalt","Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)","Bewusstseinsstörungen, Koordinationsstörungen, enge Pupillen (Miosis)"],"unbekannt":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","QT-Verlängerung, Torsade de pointes und Herzstillstand bei Überdosierung oder Missbrauch"]},"schwangerschaft":"Erfahrungen sind begrenzt; besonders im ersten Schwangerschaftsdrittel nur nach ärztlicher Abwägung anwenden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Loperamid behandelt nur das Symptom: verlorene Flüssigkeit und Salze ersetzen (z. B. mit Rehydratationslösung).","Bei Fieber, Blut im Stuhl oder fehlender Besserung nach 48 Stunden ärztlich abklären; bei Verstopfung oder Blähbauch absetzen.","Die angegebene Tageshöchstdosis nie überschreiten – Überdosen können lebensbedrohliche Herzrhythmusstörungen auslösen.","Kann Müdigkeit und Schwindel verursachen – Vorsicht beim Autofahren."],"darreichung":["Kapseln","Schmelztabletten"]},"lopinavir-ritonavir":{"wirkmechanismus":"Verhindert, dass das HI-Virus reife, ansteckende Viruspartikel bilden kann. Lopinavir hemmt die HIV-Protease, die die Vorläufer-Eiweisse des Virus (Gag-Pol-Polyprotein) zerschneidet; es entstehen nur unreife, nicht infektiöse Viren. Ritonavir in niedriger Dosis hemmt stark das Abbauenzym CYP3A4 und erhöht so die Lopinavir-Spiegel. Dadurch beeinflusst die Kombination den Abbau sehr vieler anderer Arzneimittel; gleichzeitig induziert sie andere Abbauwege (z. B. Glucuronidierung, CYP1A2, CYP2C9, CYP2C19).","nebenwirkungen":{"sehrHaeufig":["Durchfall","Übelkeit","Infektionen der oberen Atemwege"],"haeufig":["Erbrechen, Bauchschmerzen, Blähungen, Verdauungsbeschwerden, Reflux","Pankreatitis (Bauchspeicheldrüsenentzündung)","Erhöhte Blutfette (Triglyceride, Cholesterin), Blutzuckerstörungen bis Diabetes","Hepatitis, erhöhte Leberwerte","Kopfschmerzen, Schwindel, Schlaflosigkeit, Angst, periphere Neuropathie","Hautausschlag, Juckreiz, Nachtschweiss","Anämie, Neutropenie, Leukopenie","Überempfindlichkeitsreaktionen einschliesslich Nesselsucht und Angioödem"],"gelegentlich":["AV-Block, Herzinfarkt","Schlaganfall, Krampfanfälle","Tiefe Venenthrombose","Magen-Darm-Blutungen","Fettleber, Gallenwegsentzündung, erhöhtes Bilirubin","Rhabdomyolyse, Osteonekrose","Immunrekonstitutionssyndrom"],"selten":["Stevens-Johnson-Syndrom, Erythema multiforme"],"unbekannt":["QT-Verlängerung, Torsade de pointes"]},"schwangerschaft":"Kann in der Schwangerschaft eingesetzt werden, wenn es klinisch notwendig ist (umfangreiche Erfahrungen); die Lösung zum Einnehmen wegen Alkohol und Propylenglykol nicht verwenden.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Tabletten unzerkaut mit oder ohne Mahlzeit schlucken; die Lösung zum Einnehmen mit einer Mahlzeit einnehmen.","Sehr viele Wechselwirkungen: vor jedem neuen Medikament – auch Asthmasprays, Potenzmitteln und pflanzlichen Mitteln – Ärztin, Arzt oder Apotheke informieren.","Blutfette, Blutzucker und Leberwerte werden regelmässig kontrolliert."],"darreichung":["Filmtabletten","Lösung zum Einnehmen"]},"loratadin":{"wirkmechanismus":"Hemmt die Wirkung von Histamin und lindert so Niesen, Juckreiz, Fliessschnupfen und Quaddeln. Loratadin ist ein lang wirksamer, selektiver Antagonist peripherer Histamin-H1-Rezeptoren ohne nennenswerte anticholinerge Wirkung. In der Leber wird es über CYP3A4 und CYP2D6 zu Desloratadin umgewandelt, das massgeblich zur Wirkung beiträgt. Es gelangt kaum ins Gehirn und macht deshalb selten müde.","nebenwirkungen":{"haeufig":["Schläfrigkeit (Somnolenz)","Kopfschmerzen","Appetitsteigerung","Schlaflosigkeit","Nervosität und Müdigkeit bei Kindern"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Schwindel, Krampfanfälle","Herzrasen (Tachykardie), Herzklopfen","Übelkeit, Mundtrockenheit, Magenschleimhautentzündung","Leberfunktionsstörungen","Hautausschlag, Haarausfall"],"unbekannt":["Gewichtszunahme"]},"schwangerschaft":"Grosse Datenmengen zeigen kein erhöhtes Fehlbildungsrisiko; vorsichtshalber trotzdem möglichst vermeiden bzw. nur nach ärztlicher Abwägung.","stillzeit":"Loratadin und sein Wirkmetabolit gehen in die Muttermilch über; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten einnehmen.","Vor Allergie-Hauttests mindestens 48 Stunden absetzen.","Selten Müdigkeit möglich – die eigene Reaktion vor dem Autofahren prüfen."],"darreichung":["Tabletten","Retardtabletten (Kombipräparat)"]},"lorazepam":{"wirkmechanismus":"Wirkt angstlösend, beruhigend, schlaffördernd und krampflösend. Lorazepam verstärkt über die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors die Wirkung des hemmenden Botenstoffs GABA. Es wird ohne Beteiligung der Cytochrom-P450-Enzyme an Glucuronsäure gekoppelt und über die Niere ausgeschieden; wirksame Abbauprodukte entstehen nicht.","nebenwirkungen":{"sehrHaeufig":["Sedierung, Müdigkeit, Schläfrigkeit"],"haeufig":["Ataxie (Gangunsicherheit), Schwindel","Verwirrtheit","Depression oder Demaskierung einer Depression","Muskelschwäche, Kraftlosigkeit"],"gelegentlich":["Libidoveränderungen, Erektionsstörungen","Übelkeit"],"unbekannt":["Atemdepression bis Atemstillstand, Verschlechterung einer Schlafapnoe oder COPD","Anterograde Amnesie (Gedächtnislücken)","Paradoxe Reaktionen (Unruhe, Aggressivität, Halluzinationen), Enthemmung, Suizidgedanken","Abhängigkeit und Entzugssymptome","Blutbildveränderungen (Thrombozytopenie, Agranulozytose, Panzytopenie)","Anaphylaxie, allergische Hautreaktionen","Hyponatriämie (SIADH)","Blutdruckabfall, erhöhte Leberwerte, Gelbsucht"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit. Bei Anwendung gegen Ende der Schwangerschaft oder während der Geburt können beim Neugeborenen Muskelschlaffheit, Atemprobleme, Unterkühlung und Entzugssymptome auftreten.","stillzeit":"Lorazepam geht in die Muttermilch über (Müdigkeit, Trinkschwäche beim Säugling möglich). Nicht stillen, ausser nach ärztlicher Abwägung.","hinweise":["Temesta Expidet zergeht ohne Wasser auf der Zunge.","So kurz wie möglich anwenden (bei Schlafstörungen höchstens 4 Wochen, bei Angst höchstens 8–12 Wochen, jeweils einschliesslich Ausschleichen); nach längerer Einnahme langsam ausschleichen.","Kein Alkohol; Fahrtüchtigkeit beeinträchtigt.","Ältere Menschen: erhöhte Sturzgefahr, besonders nachts."],"darreichung":["Tabletten","Schmelztabletten","Injektionslösung"]},"lorlatinib":{"wirkmechanismus":"Blockiert gezielt das veränderte Wachstumssignal-Enzym ALK in Lungenkrebszellen. Lorlatinib ist ein ALK- und ROS1-Hemmer der dritten Generation, der gegen fast alle bekannten ALK-Resistenzmutationen einschliesslich G1202R wirkt. Er wurde so entwickelt, dass er gut ins Gehirn gelangt, und wirkt daher besonders auch gegen Hirnmetastasen.","nebenwirkungen":{"sehrHaeufig":["Erhöhtes Cholesterin und erhöhte Triglyceride","Wassereinlagerungen (Ödeme), Gewichtszunahme","Periphere Neuropathie (Kribbeln, Taubheit)","Kognitive Störungen (Gedächtnis-, Konzentrationsstörungen) und Stimmungsschwankungen (Reizbarkeit, Angst, Depression)","Müdigkeit, Kopfschmerzen, Schwindel","Gelenk- und Muskelschmerzen","Durchfall, Übelkeit, Verstopfung","Hautausschlag, Sehstörungen, Blutarmut, Bluthochdruck, erhöhter Blutzucker"],"haeufig":["Psychotische Symptome (Halluzinationen), Sprachstörungen, Schlafstörungen","Pneumonitis (Lungenentzündung ohne Erreger)","AV-Block (Reizleitungsstörung im Herzen)"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig. Frauen im gebärfähigen Alter müssen während und mindestens 35 Tage nach der Behandlung zuverlässig nichthormonal verhüten; Männer mit Partnerin im gebärfähigen Alter verwenden während und bis 14 Wochen danach Kondome.","stillzeit":"Während der Behandlung und 7 Tage danach nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit, unabhängig von den Mahlzeiten einnehmen; keine Grapefruit und kein Johanniskraut.","Blutfette vor Beginn und regelmässig kontrollieren – oft ist ein Cholesterinsenker nötig.","Veränderungen von Stimmung, Gedächtnis, Sprache oder Verhalten melden; Angehörige darauf aufmerksam machen.","EKG, Blutdruck und Blutzucker regelmässig kontrollieren lassen."],"darreichung":["Filmtabletten"]},"lormetazepam":{"wirkmechanismus":"Macht schläfrig und beruhigt, indem es die Wirkung eines hemmenden Botenstoffs im Gehirn verstärkt. Lormetazepam bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt die hemmende Wirkung von GABA. Es wird in der Leber direkt an Glucuronsäure gekoppelt, ohne wirksame Abbauprodukte zu bilden, und ist daher kaum von Leberenzym-Wechselwirkungen betroffen. Die Halbwertszeit beträgt etwa 10–12 Stunden.","nebenwirkungen":{"haeufig":["Müdigkeit und Benommenheit am Folgetag","Schwindel","Kopfschmerzen","Verminderte Konzentration und Reaktionsfähigkeit"],"unbekannt":["Anterograde Amnesie (Erinnerungslücken für die Zeit nach der Einnahme)","Verwirrtheit, besonders bei älteren Menschen","Paradoxe Reaktionen (Unruhe, Erregung, Aggressivität, Albträume, Halluzinationen)","Gangunsicherheit (Ataxie), Muskelschwäche und Stürze","Atemdepression (Atemdämpfung)","Abhängigkeit, Entzugserscheinungen und Rebound-Schlaflosigkeit beim Absetzen","Überempfindlichkeitsreaktionen der Haut","Blutdruckabfall"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme gegen Ende der Schwangerschaft drohen beim Neugeborenen Atemprobleme, Muskelschlaffheit, Unterkühlung und Entzugssymptome.","stillzeit":"Lormetazepam geht in die Muttermilch über – nicht anwenden bzw. abstillen.","hinweise":["Kurz vor dem Zubettgehen einnehmen und genügend Schlafzeit einplanen.","Nur kurzfristig einnehmen (in der Regel höchstens wenige Wochen); bei längerer Einnahme droht Abhängigkeit.","Fahrtüchtigkeit am Folgetag kann eingeschränkt sein; keinen Alkohol trinken.","Nach längerer Einnahme nicht abrupt absetzen, sondern schrittweise ausschleichen."],"darreichung":["Tabletten"]},"lornoxicam":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen, indem es die Bildung von Prostaglandinen hemmt. Lornoxicam hemmt die Cyclooxygenasen COX-1 und COX-2 kräftig. Anders als andere Oxicame hat es eine kurze Halbwertszeit von 3–5 Stunden. Es wird über das Leberenzym CYP2C9 abgebaut.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Übelkeit, Erbrechen, Bauchschmerzen, Dyspepsie (Verdauungsbeschwerden), Durchfall"],"gelegentlich":["Appetitlosigkeit, Gewichtsveränderungen","Schlaflosigkeit, Depression","Ohrensausen (Tinnitus), Drehschwindel","Herzklopfen, Herzrasen, Ödeme, Herzinsuffizienz","Verstopfung, Blähungen, Mundtrockenheit, Gastritis, Magen- oder Zwölffingerdarmgeschwür","Erhöhte Leberwerte","Hautausschlag, Juckreiz, Schwitzen, Nesselsucht, Haarausfall","Gelenkschmerzen"],"selten":["Anämie, Thrombozytopenie, Leukopenie, verlängerte Blutungszeit","Überempfindlichkeitsreaktionen, Bronchospasmus (Verkrampfung der Atemwege)","Verwirrtheit, Schläfrigkeit, Kribbeln, Geschmacksstörungen","Bluthochdruck, Blutungen","Magen-Darm-Blutung (Teerstuhl, Bluterbrechen), Durchbruch eines Geschwürs","Erhöhte Harnstoff- und Kreatininwerte"],"sehrSelten":["Leberschädigung","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"],"unbekannt":["Erhöhtes Risiko für Herzinfarkt und Schlaganfall"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach strenger ärztlicher Abwägung; ab der 20. Woche können NSAR die Nierenfunktion des Ungeborenen beeinträchtigen. Im letzten Drittel kontraindiziert.","stillzeit":"Keine ausreichenden Daten; in der Stillzeit nicht empfohlen.","hinweise":["Mit ausreichend Flüssigkeit vor oder mit einer Mahlzeit einnehmen; so kurz und so niedrig dosiert wie möglich.","Nicht mit anderen NSAR kombinieren.","Schwindel und Schläfrigkeit können die Fahrtüchtigkeit beeinträchtigen.","Bei Langzeitbehandlung Blutbild, Leber- und Nierenwerte kontrollieren lassen."],"darreichung":["Filmtabletten"]},"losartan":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Wirkung des gefässverengenden Hormons Angiotensin II an seinem Rezeptor blockiert. Losartan und vor allem sein in der Leber (über CYP2C9 und CYP3A4) gebildeter, stärker wirksamer Metabolit blockieren selektiv den AT1-Rezeptor. Dadurch weiten sich die Gefässe, die Aldosteronausschüttung sinkt und die Niere scheidet mehr Salz und Wasser aus. Anders als ACE-Hemmer beeinflussen Sartane den Bradykinin-Abbau nicht, weshalb Reizhusten selten ist; Losartan senkt zudem leicht die Harnsäure im Blut.","nebenwirkungen":{"haeufig":["Schwindel, Drehschwindel","Hypotonie (tiefer Blutdruck), auch beim Aufstehen – besonders bei Flüssigkeitsmangel oder Herzschwäche","Hyperkaliämie (erhöhtes Kalium)","Nierenfunktionsstörung bis Nierenversagen, Anstieg von Harnstoff und Kreatinin","Müdigkeit, Schwäche","Hypoglykämie (Unterzuckerung) bei Diabetes mit Nierenschaden; Anämie (Blutarmut) bei Herzschwäche"],"gelegentlich":["Kopfschmerzen, Schläfrigkeit, Schlafstörungen","Herzklopfen, Angina pectoris","Atemnot, Husten","Bauchschmerzen, Verstopfung, Durchfall, Übelkeit, Erbrechen","Nesselsucht, Juckreiz, Hautausschlag","Ödeme (Wassereinlagerungen)"],"selten":["Überempfindlichkeitsreaktionen: Anaphylaxie, Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen), Vaskulitis","Kribbeln (Parästhesien)","Synkope (Ohnmacht), Vorhofflimmern, Schlaganfall","Hepatitis, Anstieg der Leberwerte"],"unbekannt":["Thrombozytopenie (Mangel an Blutplättchen)","Hyponatriämie (Natriummangel)","Depression, Migräne, Geschmacksstörungen, Ohrensausen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Lichtempfindlichkeit","Muskel- und Gelenkschmerzen, Rhabdomyolyse (Muskelzerfall)","Erektionsstörungen"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten zum Übergang in die Muttermilch fehlen; besser untersuchte Alternativen wählen.","hinweise":["Täglich etwa zur gleichen Zeit einnehmen, unabhängig von den Mahlzeiten.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel und Kaliumpräparate nur nach ärztlicher Rücksprache.","Zu Beginn kann Schwindel auftreten – Vorsicht beim Autofahren.","Bei starkem Durchfall, Erbrechen oder Flüssigkeitsmangel ärztlich klären, ob die Einnahme vorübergehend pausiert werden soll."],"darreichung":["Filmtabletten"]},"loteprednol":{"wirkmechanismus":"Hemmt Entzündung, Rötung und Schwellung am Auge. Loteprednoletabonat ist ein Glukokortikoid, das über den Glukokortikoid-Rezeptor die Bildung entzündungsfördernder Botenstoffe wie Prostaglandine und Leukotriene unterdrückt. Als sogenanntes «Soft-Steroid» wird es nach der Wirkung durch Esterasen rasch zu unwirksamen Abbauprodukten gespalten, sodass kaum Wirkstoff in den Körper gelangt. Den Augeninnendruck kann es trotzdem erhöhen.","nebenwirkungen":{"unbekannt":["Erhöhter Augeninnendruck, Glaukom mit möglicher Sehnervschädigung","Grauer Star (hintere subkapsuläre Katarakt)","Augeninfektionen und verzögerte Wundheilung, Durchbruch von Horn- oder Lederhaut","Verschwommenes Sehen, Lichtscheu","Brennen beim Eintropfen, Augenrötung, Jucken, Fremdkörpergefühl, Tränenfluss","Trockenes Auge, Bindehautschwellung (Chemosis), Augenausfluss","Kopfschmerzen, Schnupfen, Rachenentzündung"]},"schwangerschaft":"Nur nach ärztlicher Abwägung anwenden; Daten beim Menschen fehlen.","stillzeit":"Nicht bekannt, ob Loteprednol in die Muttermilch übergeht; nur nach ärztlicher Abwägung anwenden.","hinweise":["Vor Gebrauch gut schütteln (Suspension).","Nicht länger als verordnet anwenden; bei Anwendung über 10 Tage den Augeninnendruck kontrollieren lassen.","Nach dem Eintropfen kann das Sehen kurz verschwommen sein – erst danach Auto fahren."],"darreichung":["Augentropfen (Suspension)"]},"lumacaftor-ivacaftor":{"wirkmechanismus":"Hilft, mehr funktionsfähige CFTR-Chloridkanäle an die Zelloberfläche zu bringen und deren Öffnung zu verbessern. Lumacaftor ist ein CFTR-Korrektor: Er verbessert die Faltung des durch die F508del-Mutation fehlgefalteten CFTR-Proteins, sodass mehr davon die Zelloberfläche erreicht. Ivacaftor ist ein Potentiator, der die Öffnungswahrscheinlichkeit dieser Kanäle erhöht. Lumacaftor ist zudem ein starker CYP3A-Induktor und verursacht zahlreiche Wechselwirkungen.","nebenwirkungen":{"sehrHaeufig":["Atemnot (Dyspnoe), vor allem zu Behandlungsbeginn","Husten mit Auswurf, vermehrter Auswurf","Nasen-Rachen-Entzündung","Kopfschmerzen","Schwindel","Bauchschmerzen, Durchfall, Übelkeit"],"haeufig":["Infektionen der oberen Atemwege, Schnupfen","Engegefühl in der Brust, Bronchospasmus (Verkrampfung der Atemwege)","Erbrechen, Blähungen","Erhöhte Leberwerte, erhöhte CK (Muskelenzym)","Hautausschlag","Unregelmässige oder schmerzhafte Periode, Zwischenblutungen","Ohrenschmerzen, Ohrgeräusche (Tinnitus)","Knoten in der Brust"],"gelegentlich":["Bluthochdruck","Cholestatische Hepatitis, hepatische Enzephalopathie (bei vorbestehender Lebererkrankung)","Ausbleibende oder verstärkte Periode","Brustvergrösserung beim Mann (Gynäkomastie)"],"unbekannt":["Linsentrübung (Katarakt) bei Kindern"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Ob die Wirkstoffe in die Muttermilch übergehen, ist nicht bekannt; Nutzen und Risiko ärztlich abwägen.","hinweise":["Mit einer fetthaltigen Mahlzeit einnehmen.","Hormonale Verhütung wirkt nicht zuverlässig: zusätzlich eine Barrieremethode (Kondom) verwenden.","Vor jedem neuen Medikament, auch rezeptfreien und pflanzlichen, die Wechselwirkungen prüfen lassen.","Leberwerte, Blutdruck und bei Kindern die Augen regelmässig kontrollieren."],"darreichung":["Filmtabletten","Granulat (Beutel)"]},"lumasiran":{"wirkmechanismus":"Senkt die übermässige Bildung von Oxalat in der Leber, das bei primärer Hyperoxalurie Typ 1 Nierensteine und Organschäden verursacht. Lumasiran ist eine kleine interferierende RNA (siRNA), die über eine GalNAc-Zuckerverbindung gezielt in Leberzellen gelangt. Dort führt sie zum Abbau der Boten-RNA des Enzyms Glykolatoxidase (Gen HAO1). Dadurch entsteht weniger Glyoxylat als Ausgangsstoff für Oxalat; das stattdessen anfallende Glykolat ist gut löslich und wird über den Urin ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Rötung, Schmerz, Juckreiz, Schwellung)"],"haeufig":["Bauchschmerzen"]},"schwangerschaft":"Begrenzte Erfahrungen; nur nach ärztlicher Abwägung von Nutzen und Risiko.","stillzeit":"Über Stillen oder Behandlung wird nach ärztlicher Abwägung entschieden.","hinweise":["Wird von einer Fachperson unter die Haut gespritzt: zu Beginn monatlich, danach je nach Körpergewicht alle 1 oder 3 Monate.","Oxalatwerte in Urin oder Blut sowie die Nierenfunktion werden regelmässig kontrolliert.","Begleitmassnahmen wie reichliches Trinken nach ärztlicher Anweisung weiterführen."],"darreichung":["Injektionslösung"]},"lurasidon":{"wirkmechanismus":"Mildert psychotische Symptome wie Wahn, Halluzinationen und Denkstörungen. Lurasidon blockiert Dopamin-D2-, Serotonin-5-HT2A- und 5-HT7-Rezeptoren und wirkt als Partialagonist an Serotonin-5-HT1A-Rezeptoren. Histamin-H1- und Muskarinrezeptoren werden kaum beeinflusst, was die geringe Neigung zu Gewichtszunahme und anticholinergen Nebenwirkungen erklärt. Es wird fast vollständig über CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Akathisie (Sitzunruhe, Bewegungsdrang)","Schläfrigkeit"],"haeufig":["Gewichtszunahme","Schlaflosigkeit, Unruhe, Angst","Parkinsonismus, Dystonie (Muskelverkrampfungen), Dyskinesien, Schwindel","Übelkeit, Erbrechen, Verdauungsbeschwerden, Bauchschmerzen","Vermehrter Speichelfluss, Mundtrockenheit","Muskelsteifigkeit","Müdigkeit, erhöhte Kreatinkinase (Muskelenzym)"],"gelegentlich":["Erhöhter Prolaktinspiegel, erhöhter Blutzucker","Albträume","Spätdyskinesien (unwillkürliche Bewegungen)","Verschwommenes Sehen","Herzrasen, Blutdruckabfall beim Aufstehen","Durchfall"],"selten":["Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung)","Suizidales Verhalten","Angioödem (Schwellung von Gesicht und Rachen)","Rhabdomyolyse (Muskelzerfall)","Brustvergrösserung, Milchfluss, Ausbleiben der Regel, Erektionsstörung"],"unbekannt":["Stevens-Johnson-Syndrom (schwere Hautreaktion)","Veränderungen des Blutbilds (Leukopenie, Neutropenie)","Entzugssymptome beim Neugeborenen nach Einnahme in der Schwangerschaft"]},"schwangerschaft":"Begrenzte Erfahrungen; nur nach strenger ärztlicher Abwägung. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen und Entzugssymptome auftreten.","stillzeit":"Nur nach ärztlicher Abwägung; ob Lurasidon beim Menschen in die Muttermilch übergeht, ist nicht ausreichend bekannt.","hinweise":["Einmal täglich mit einer Mahlzeit (mindestens etwa 350 kcal) einnehmen – nüchtern wird nur ein Teil aufgenommen.","Keinen Grapefruitsaft trinken und neue Medikamente (auch Johanniskraut) nur nach Rücksprache einnehmen.","Kann müde machen – Vorsicht beim Autofahren, Alkohol meiden."],"darreichung":["Filmtabletten"]},"lurbinectedin":{"wirkmechanismus":"Hemmt das Ablesen der Erbinformation in Krebszellen und lässt diese absterben. Lurbinectedin bindet an Guanin-Reste in der kleinen Furche der DNA und bildet Addukte, die die DNA-Helix verbiegen. Dadurch wird die aktive Transkription durch die RNA-Polymerase II blockiert, es entstehen DNA-Doppelstrangbrüche und die Zellen gehen in den programmierten Zelltod. Zusätzlich hemmt es die Transkription in tumorfördernden Makrophagen.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Thrombozytopenie, Anämie","Müdigkeit, Schwäche","Übelkeit, Erbrechen, Verstopfung, Durchfall","Appetitlosigkeit","Erhöhte Leberwerte und erhöhtes Kreatinin","Atemnot, Husten","Muskel- und Knochenschmerzen","Fieber"],"haeufig":["Febrile Neutropenie (Fieber bei Neutropenie)","Lungenentzündung und andere Infektionen","Periphere Neuropathie (Nervenschädigung)","Kopfschmerzen","Bauchschmerzen, Mundschleimhautentzündung"],"unbekannt":["Sepsis (Blutvergiftung)","Rhabdomyolyse (Muskelzerfall)","Gewebeschädigung bei Extravasation"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen sollen bis 6 Monate, Männer bis 4 Monate nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 2 Wochen nach der letzten Dosis nicht stillen.","hinweise":["Vor jeder Gabe werden Blutbild und Leberwerte kontrolliert; Fieber oder Infektzeichen sofort melden.","Vor der Infusion werden Mittel gegen Übelkeit gegeben.","Grapefruit und Johanniskraut meiden; neue Medikamente nur nach Rücksprache."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"luspatercept":{"wirkmechanismus":"Hilft unreifen roten Blutkörperchen im Knochenmark, fertig auszureifen. Luspatercept ist ein Fusionsprotein aus einem veränderten Activin-Rezeptor Typ IIB und dem Fc-Teil eines menschlichen Antikörpers. Es fängt bestimmte Botenstoffe der TGF-beta-Familie (u. a. GDF11, Activin B) ab, die über den Smad2/3-Signalweg die späte Ausreifung der roten Blutkörperchen hemmen. Dadurch steigen die Zahl reifer roter Blutkörperchen und das Hämoglobin.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit, Schwäche","Kopfschmerzen","Schwindel","Durchfall, Übelkeit","Rücken-, Gelenk- und Knochenschmerzen","Atemnot (Dyspnoe)","Infektionen der oberen Atemwege"],"haeufig":["Bluthochdruck (Hypertonie)","Thromboembolische Ereignisse (Thrombosen, Lungenembolie, Schlaganfall)","Ohnmacht (Synkope)","Erhöhte Harnsäure im Blut","Überempfindlichkeitsreaktionen","Reaktionen an der Injektionsstelle","Grippeähnliche Beschwerden"],"unbekannt":["Extramedulläre Blutbildungsherde, z. B. mit Einengung des Rückenmarks"]},"schwangerschaft":"Kontraindiziert (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen während der Behandlung und bis 3 Monate nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 3 Monate nach der letzten Dosis nicht stillen.","hinweise":["Wird alle 3 Wochen unter die Haut gespritzt; vor jeder Gabe werden Hämoglobin und Blutdruck kontrolliert.","Die Wirkung zeigt sich oft erst nach einigen Wochen; Transfusionen werden je nach Ansprechen weitergeführt.","Zeichen einer Thrombose (Beinschwellung, Brustschmerz, Atemnot, Lähmung) sofort melden."],"darreichung":["Pulver zur Herstellung einer Injektionslösung"]},"lutetium-177lu-oxodotreotid":{"wirkmechanismus":"Bindet gezielt an Tumorzellen mit Somatostatin-Rezeptoren und bestrahlt sie von innen (Peptid-Rezeptor-Radionuklidtherapie). Oxodotreotid ist ein Somatostatin-Analogon, das mit hoher Affinität an Somatostatin-Rezeptoren vom Subtyp 2 bindet, die viele neuroendokrine Tumoren stark ausbilden, und mit dem Rezeptor in die Zelle aufgenommen wird. Lutetium-177 sendet Betastrahlung mit einer Reichweite von wenigen Millimetern aus, die DNA-Schäden und den Tod der Tumorzellen bewirkt; die Halbwertszeit beträgt rund 6,7 Tage. Die Ausscheidung erfolgt über die Nieren; eine gleichzeitige Aminosäure-Infusion (Lysin und Arginin) verringert die Strahlenbelastung der Nieren.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Erbrechen","Thrombozytopenie (Mangel an Blutplättchen)","Lymphopenie (Mangel an Lymphozyten)","Anämie (Blutarmut)"],"haeufig":["Leukopenie und Neutropenie (Mangel an weissen Blutkörperchen)","Myelodysplastisches Syndrom (Knochenmarkerkrankung), auch Jahre nach der Behandlung"],"gelegentlich":["Akute Leukämie"],"unbekannt":["Hormonelle Krise (Hautrötung, Durchfall, Blutdruckabfall)","Nierenschädigung bis Nierenversagen","Leberschädigung, besonders bei Lebermetastasen","Müdigkeit, verminderter Appetit","Bauchschmerzen, Durchfall","Haarausfall (meist leicht und vorübergehend)","Verminderte Fruchtbarkeit"]},"schwangerschaft":"Kontraindiziert. Vor Beginn muss eine Schwangerschaft ausgeschlossen werden; Frauen und Männer müssen während der Behandlung und für mehrere Monate nach der letzten Dosis wirksam verhüten (Dauer gemäss ärztlicher Anweisung).","stillzeit":"Während der Behandlung und für eine festgelegte Zeit danach nicht stillen; Wiederaufnahme nur nach ärztlicher Rücksprache.","hinweise":["Wird in der Regel 4-mal im Abstand von 8 Wochen als Infusion gegeben, zusammen mit einer Aminosäure-Infusion zum Nierenschutz und einem Mittel gegen Übelkeit.","Blutbild, Nieren- und Leberwerte vor jeder Gabe kontrollieren.","Am Behandlungstag und am Tag danach viel trinken und häufig Wasser lassen; die Strahlenschutz-Anweisungen (Abstand zu Kleinkindern und Schwangeren, Toilettenhygiene) einhalten.","Langzeit-Somatostatin-Analoga nur nach Absprache mit dem Behandlungsteam pausieren bzw. fortsetzen."],"darreichung":["Infusionslösung"]},"lutetium-177lu-vipivotid-tetraxetan":{"wirkmechanismus":"Bindet gezielt an Prostatakrebszellen und bestrahlt sie von innen (Radioligandentherapie). Vipivotid-Tetraxetan (PSMA-617) bindet mit hoher Affinität an das prostataspezifische Membranantigen (PSMA), das auf Prostatakrebszellen stark vermehrt vorkommt, und wird in die Zelle aufgenommen. Lutetium-177 gibt Betastrahlung mit einer Reichweite von wenigen Millimetern ab, die DNA-Schäden und den Zelltod auslöst; die Halbwertszeit beträgt rund 6,6 Tage. Ausgeschieden wird es hauptsächlich über die Nieren; auch Speichel- und Tränendrüsen nehmen die Substanz auf, was Mund- und Augentrockenheit erklärt.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit (Fatigue)","Mundtrockenheit","Übelkeit, Erbrechen","Verminderter Appetit","Obstipation (Verstopfung), Durchfall","Anämie (Blutarmut)","Thrombozytopenie (Mangel an Blutplättchen)","Lymphopenie und Leukopenie (Mangel an weissen Blutkörperchen)"],"haeufig":["Neutropenie (Mangel an Abwehrzellen)","Akute Nierenschädigung","Dysgeusie (Geschmacksstörung)","Trockene Augen"],"unbekannt":["Panzytopenie (Mangel an allen Blutzellen) bis Knochenmarkversagen","Vorübergehende oder bleibende Unfruchtbarkeit","Langzeitrisiko für Zweitkrebs durch die Strahlenbelastung"]},"schwangerschaft":"Nicht zur Anwendung bei Frauen bestimmt. Männer müssen während der Behandlung und bis 14 Wochen nach der letzten Dosis Kondome verwenden und dürfen kein Kind zeugen.","stillzeit":"Nicht zur Anwendung bei Frauen bestimmt.","hinweise":["Wird in der Regel bis zu 6-mal im Abstand von 6 Wochen gegeben; vorher wird mit einer PSMA-PET (z. B. Gallium-68-Gozetotid) geprüft, ob der Tumor PSMA trägt.","Blutbild und Nierenwerte vor jeder Gabe kontrollieren; viel trinken und häufig Wasser lassen.","Strahlenschutz-Anweisungen einhalten: in den ersten Tagen Abstand zu Kleinkindern und Schwangeren, getrennt schlafen, Toilette im Sitzen benutzen und mehrmals spülen.","Der Androgenentzug (z. B. GnRH-Analogon) wird in der Regel weitergeführt."],"darreichung":["Injektions- bzw. Infusionslösung"]},"lutropin-alfa":{"wirkmechanismus":"Ersetzt das fehlende luteinisierende Hormon (LH), das die Eierstöcke für die Reifung der Eibläschen brauchen. Lutropin alfa ist gentechnisch hergestelltes menschliches LH; es bindet an LH-Rezeptoren der Thekazellen und regt dort die Bildung von Androgenen an, die in den Granulosazellen unter FSH-Einfluss zu Östradiol umgewandelt werden. Bei schwerem Mangel an beiden Hormonen ist diese Kombination für eine normale Follikelentwicklung nötig.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Reaktionen an der Einstichstelle (Schmerzen, Rötung, Bluterguss, Schwellung)","Bauchschmerzen, Übelkeit, Erbrechen, Durchfall","Leichtes bis mittelschweres ovarielles Überstimulationssyndrom (OHSS)","Eierstockzysten","Brust- und Beckenschmerzen"],"gelegentlich":["Schweres ovarielles Überstimulationssyndrom"],"sehrSelten":["Thromboembolie (meist bei schwerem OHSS)","Überempfindlichkeitsreaktionen bis Anaphylaxie"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Wird immer zusammen mit FSH angewendet (z. B. als Fixkombination mit Follitropin alfa, Pergoveris); Injektion unter die Haut nach Anleitung.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung im Fertigpen","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"lymecyclin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, auch der an der Akne beteiligten Hautbakterien (Cutibacterium acnes). Lymecyclin ist eine gut wasserlösliche Verbindung von Tetracyclin mit der Aminosäure Lysin. Es bindet an die 30S-Untereinheit der bakteriellen Ribosomen und verhindert die Anlagerung der Transfer-RNA, sodass die Eiweisssynthese stoppt (bakteriostatisch). Bei Akne wirkt es zusätzlich entzündungshemmend.","nebenwirkungen":{"haeufig":["Übelkeit","Bauchschmerzen","Durchfall","Kopfschmerzen"],"unbekannt":["Lichtempfindlichkeit (phototoxische Hautreaktionen)","Überempfindlichkeitsreaktionen bis zur Anaphylaxie, Nesselsucht, Angioödem","Erhöhter Hirndruck (Pseudotumor cerebri) mit Kopfschmerzen und Sehstörungen","Speiseröhrenentzündung und -geschwüre, Schluckbeschwerden","Zahnverfärbung bei Kindern","Leberschäden, Gelbsucht, erhöhte Leberwerte","Blutbildveränderungen (Neutropenie, Thrombozytopenie)","Pseudomembranöse Kolitis (schwere Darmentzündung)"]},"schwangerschaft":"Kontraindiziert: Tetracycline können beim Ungeborenen bleibende Zahnverfärbungen und Störungen des Knochenwachstums verursachen.","stillzeit":"Kontraindiziert: Lymecyclin geht in die Muttermilch über.","hinweise":["Kapseln aufrecht mit einem grossen Glas Wasser schlucken, nicht unmittelbar vor dem Schlafengehen (Gefahr von Speiseröhrengeschwüren).","Antazida, Eisen-, Calcium-, Magnesium- und Zinkpräparate mit 2–3 Stunden Abstand einnehmen.","Starke Sonne und Solarium meiden; Sonnenschutz verwenden.","Die Wirkung bei Akne zeigt sich meist erst nach einigen Wochen."],"darreichung":["Kapseln"]}});
